COPY public.digest_tip (id, sequence, group_id, create_uid, write_uid, name, tip_description, create_date, write_date) FROM stdin;
3	2300	1	1	1	{"en_US": "Tip: A calculator in Odoo", "es_ES": "Consejo: una calculadora en Odoo"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: A calculator in Odoo</p>\\n    <p class=\\"tip_content\\">When editing a number, you can use formulae by typing the `=` character. This is useful when computing a margin or a discount on a quotation, sale order or invoice.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-calculator.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: una calculadora en Odoo</p>\\n    <p class=\\"tip_content\\">Cuando edite un número, puede utilizar fórmulas al escribir el carácter `=`. Esto es útil cuando calcula un margen o un descuento en un presupuesto, pedido de venta o factura.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-calculator.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-26 18:43:13.291597	2025-11-26 18:43:13.291597
4	2400	1	1	1	{"en_US": "Tip: How to ping users in internal notes?", "es_ES": "Consejo: ¿Cómo notificar usuarios en las notas internas?"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: How to ping users in internal notes?</p>\\n    <p class=\\"tip_content\\">Type \\"@\\" to notify someone in a message, or \\"#\\" to link to a channel. Try to notify @OdooBot to test the feature.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-notifications.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: ¿Cómo notificar usuarios en las notas internas?</p>\\n    <p class=\\"tip_content\\">Escriba \\"@\\" para enviar una notificación a alguien por medio de un mensaje, o \\"#\\" para vincular un canal. Intente enviar una notificación a @OdooBot para probar esta función.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-notifications.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-26 18:43:13.291597	2025-11-26 18:43:13.291597
5	2500	1	1	1	{"en_US": "Tip: Knowledge is power", "es_ES": "Consejo: el conocimiento es poder"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Knowledge is power</p>\\n    <p class=\\"tip_content\\">When following documents, use the pencil icon to fine-tune the information you want to receive.\\nFollow a project / sales team to keep track of this project's tasks / this team's opportunities.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-following.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: el conocimiento es poder</p>\\n    <p class=\\"tip_content\\">Cuando siga documentos, use el icono de lápiz para ajustar la información que desea recibir.\\nSiga un proyecto o un equipo de ventas para llevar el seguimiento de las tareas de este proyecto o las oportunidades de este equipo.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-following.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-26 18:43:13.291597	2025-11-26 18:43:13.291597
1	800	1	1	1	{"en_US": "Tip: Speed up your workflow with shortcuts", "es_ES": "Consejo: acelere su flujo de trabajo con accesos rápidos"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Speed up your workflow with shortcuts</p>\\n    <p class=\\"tip_content\\">Press ALT in any screen to highlight shortcuts for every button in the screen. It is useful to process multiple documents in batch.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-alt-shortcuts.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: acelere su flujo de trabajo con accesos rápidos</p>\\n    <p class=\\"tip_content\\">Presiona ALT en cualquier pantalla para resaltar accesos rápidos para cada botón en la pantalla. Es útil para procesar múltiples documentos en lote.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-alt-shortcuts.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-26 18:43:13.291597	2025-11-26 20:43:33.152751
2	2100	1	1	1	{"en_US": "Tip: Click on an avatar to chat with a user", "es_ES": "Consejo: Haga clic en un avatar para chatear con el usuario"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Click on an avatar to chat with a user</p>\\n    <p class=\\"tip_content\\">Have a question about a document? Click on the responsible user's picture to start a conversation. If his avatar has a green dot, he is online.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-avatar.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: Haga clic en un avatar para chatear con un usuario</p>\\n    <p class=\\"tip_content\\">¿Tienes una pregunta sobre el documento? Haga clic en la fotografía del usuario responsable para iniciar una conversación. Si el avatar tiene un punto verde, está en línea.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-avatar.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-26 18:43:13.291597	2025-11-28 07:11:54.533234
6	3300	1	1	1	{"en_US": "Tip: Join the Dark Side", "es_ES": "Consejo: únase al lado oscuro"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Join the Dark Side</p>\\n    <p class=\\"tip_content\\">Feeling eye strain? Give your eyes a break by switching to Dark Mode.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/18-web-dark-theme.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: únase al lado oscuro</p>\\n    <p class=\\"tip_content\\">¿Necesita descansar su vista? Use el modo oscuro.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/18-web-dark-theme.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-26 18:43:13.291597	2025-11-26 18:43:13.291597
7	3800	1	1	1	{"en_US": "Tip: Personalize your Home Menu", "es_ES": "Consejo: personalice su menú principal"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Personalize your Home Menu</p>\\n    <p class=\\"tip_content\\">Click and hold on a Menu Item to reorder your Apps to your liking.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/18-web-app-order.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: personalice su menú principal</p>\\n    <p class=\\"tip_content\\">Haga clic y mantenga presionado un elemento del menú para reordenar sus aplicaciones a su gusto.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/18-web-app-order.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-26 18:43:13.291597	2025-11-26 18:43:13.291597
9	700	28	1	1	{"en_US": "Tip: No need to print, put in an envelop and post your invoices", "es_ES": "Consejo: no es necesario que imprima, ponga en un sobre y envíe sus facturas"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: No need to print, put in an envelop and post your invoices</p>\\n    <p class=\\"tip_content\\">Use the “<i>Send by Post</i>” option to post invoices automatically. For the cost of a local stamp, we do all the manual work: your invoice will be printed in the right country, put in an envelop and sent by snail mail. Use this feature from the list view to post hundreds of invoices in bulk.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/invoice-stamps.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: no es necesario que imprima, ponga en un sobre y envíe sus facturas</p>\\n    <p class=\\"tip_content\\">Utilice la opción \\"<i>Enviar por correo electrónico</i>\\" para registrar facturas automáticamente. Por el coste de un sello local, hacemos todo el trabajo manual: su factura se imprimirá en el país correcto, se colocará en un sobre y se enviará por correo postal. Utilice esta función de la vista de lista para registrar cientos de facturas de forma masiva.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/invoice-stamps.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-28 09:05:18.991518	2025-11-28 09:05:18.991518
8	3500	20	1	1	{"en_US": "Tip: Where's Bryan?", "es_ES": "Consejo: ¿Dónde está Brian?"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Where's Bryan?</p>\\n    <p class=\\"tip_content\\">Activate Remote Work to let Employees specify where they are working from.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/hr/static/src/img/18-hr-work-location.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: ¿Dónde está Brian?</p>\\n    <p class=\\"tip_content\\">Habilite la función de teletrabajo para permitir que los empleados especifiquen desde dónde están trabajando.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/hr/static/src/img/18-hr-work-location.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-26 18:43:13.633684	2025-11-26 18:43:13.633684
10	3100	28	1	1	{"en_US": "Tip: Stop chasing the Documents you need", "es_ES": "Consejo: deje de buscar los documentos que necesita"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Stop chasing the Documents you need</p>\\n    <p class=\\"tip_content\\">Missing a document for a banking statement? Use the Documents apps to request it and let the owner upload it at the right place.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/18-invoice-request-document.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: deje de buscar los documentos que necesita</p>\\n    <p class=\\"tip_content\\">¿Falta un documento para un extracto bancario? Use la aplicación Documentos para solicitarlo y permita que el propietario lo suba al lugar correcto.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/18-invoice-request-document.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-28 09:05:18.991518	2025-11-28 09:05:18.991518
12	1300	37	1	1	{"en_US": "Tip: Create tasks from incoming emails", "es_ES": "Consejo: cree tareas desde sus correos electrónicos"}	{"en_US": "<div>\\n    <t t-set=\\"project_record\\" t-value=\\"object.env['project.project'].search([('alias_name', '!=', False), ('alias_domain_id', '!=', False)], limit=1, order='sequence asc')\\"></t>\\n    <p class=\\"tip_title\\">Tip: Create tasks from incoming emails</p>\\n    <t t-if=\\"project_record.alias_email\\">\\n        <p class=\\"tip_content\\">Emails sent to <a t-attf-href=\\"mailto:{{project_record.alias_email}}\\" target=\\"_blank\\" style=\\"color: #714B67; text-decoration: none;\\"><t t-out=\\"project_record.alias_email\\"></t></a> will generate tasks in your <t t-out=\\"project_record.name\\"></t> project.</p>\\n    </t>\\n    <t t-else=\\"\\">\\n        <p class=\\"tip_content\\">Create tasks by sending an email to the email address of your project.</p>\\n    </t>\\n</div>\\n            ", "es_ES": "<div>\\n    <t t-set=\\"project_record\\" t-value=\\"object.env['project.project'].search([('alias_name', '!=', False), ('alias_domain_id', '!=', False)], limit=1, order='sequence asc')\\"></t>\\n    <p class=\\"tip_title\\">Consejo: cree tareas desde sus correos electrónicos</p>\\n    <t t-if=\\"project_record.alias_email\\">\\n        <p class=\\"tip_content\\">Correos electrónicos enviados a <a t-attf-href=\\"mailto:{{project_record.alias_email}}\\" target=\\"_blank\\" style=\\"color: #714B67; text-decoration: none;\\"><t t-out=\\"project_record.alias_email\\"></t></a> generarán tareas en su proyecto <t t-out=\\"project_record.name\\"></t> .</p>\\n    </t>\\n    <t t-else=\\"\\">\\n        <p class=\\"tip_content\\">Cree tareas al enviar un correo electrónico a la dirección de correo electrónico de su proyecto.</p>\\n    </t>\\n</div>\\n            "}	2025-11-28 09:09:08.740765	2025-11-28 09:09:08.740765
14	3900	38	1	1	{"en_US": "Tip: Project-Specific Fields", "es_ES": "Consejo: campos específicos para sus proyectos"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Project-Specific Fields</p>\\n    <p class=\\"tip_content\\">Add project-specific property fields on tasks to customize your project management process.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/project/static/src/img/18-project-property-fields.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: campos específicos para sus proyectos</p>\\n    <p class=\\"tip_content\\">Añada campos de propiedad específicos al proyecto a las tareas para personalizar su proceso de gestión de proyectos.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/project/static/src/img/18-project-property-fields.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2025-11-28 09:09:08.740765	2025-11-28 09:09:08.740765
