\\"relation_field\\" invisible=\\"ttype != 'one2many'\\" readonly=\\"ttype != 'one2many'\\" required=\\"ttype == 'one2many'\\"/>\\n                                        <field name=\\"relation_table\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                        <field name=\\"column1\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                        <field name=\\"column2\\" groups=\\"base.group_no_one\\" invisible=\\"ttype != 'many2many' or state != 'manual'\\" readonly=\\"ttype != 'many2many' or state != 'manual'\\"/>\\n                                        <field name=\\"domain\\" groups=\\"base.group_no_one\\" invisible=\\"ttype not in ['many2one', 'one2many', 'many2many']\\" readonly=\\"ttype not in ['many2one', 'one2many', 'many2many']\\"/>\\n                                        <field name=\\"currency_field\\" invisible=\\"ttype != 'monetary'\\" readonly=\\"ttype != 'monetary'\\"/>\\n                                    </group>\\n                                </group>\\n                                <group string=\\"HTML/Propiedades de depuración\\" invisible=\\"ttype != 'html'\\">\\n                                    <group>\\n                                        <field name=\\"sanitize\\" invisible=\\"ttype != 'html'\\" readonly=\\"ttype != 'html'\\"/>\\n                                        <field name=\\"sanitize_overridable\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_tags\\" invisible=\\"ttype != 'html' or sanitize == False\\" readonly=\\"ttype != 'html' or sanitize == False\\"/>\\n                                        <field name=\\"sanitize_attributes\\