\\" column_invisible=\\"True\\"/>\\n                            <button string=\\"Grant Access\\" name=\\"action_grant_access\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"is_portal or is_internal or email_state != 'ok'\\"/>\\n                            <button string=\\"Revoke Access\\" name=\\"action_revoke_access\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"not is_portal or is_internal\\"/>\\n                            <button string=\\"Re-Invite\\" name=\\"action_invite_again\\" type=\\"object\\" class=\\"btn-secondary\\" invisible=\\"not is_portal or is_internal or email_state != 'ok'\\"/>\\n                            <button string=\\"Internal User\\" invisible=\\"not is_internal\\" disabled=\\"True\\" title=\\"This partner is linked to an internal User and already has access to the Portal.\\"/>\\n                        </list>\\n                    </field>\\n                    <footer>\\n                        <button string=\\"Close\\" class=\\"btn-primary\\" special=\\"save\\" data-hotkey=\\"v\\"/>\\n                    </footer>\\n                </form>", "es_ES": "<form string=\\"Administración de acceso al portal\\">\\n                    <div class=\\"mb-3\\">\\n                        Seleccione que contactos deben pertenecer al portal en la siguiente lista.\\nLa dirección de correo electrónico de cada contacto seleccionado debe ser válida y única.\\nSi es necesario, puede corregir una dirección de correo de un contacto directamente en la lista.\\n                    </div>\\n                    <field name=\\"welcome_message\\" placeholder=\\"Este texto aparece al final del correo electrónico que reciben los nuevos usuarios del portal.\\" class=\\"mb-3\\"/>\\n                    <field name=\\"user_ids\\" class=\\"o_portal_wizard_user_one2many\\" widget=\\"portal_wizard_user_one2many\\">\\n                        <list string=\\"Contactos\\" editable=\\"bottom\\" create=\\"false\\" delete=\\"false\\">\\n           