laceholder=\\"Street 2...\\" class=\\"o_address_street\\"/>\\n                                <field name=\\"city\\" placeholder=\\"City\\" class=\\"o_address_city\\"/>\\n                                <field name=\\"state_id\\" placeholder=\\"State\\" class=\\"o_address_state\\" options=\\"{'no_open': True, 'no_quick_create': True}\\" context=\\"{'country_id': country_id, 'default_country_id': country_id, 'zip': zip}\\"/>\\n                                <field name=\\"zip\\" placeholder=\\"ZIP\\" class=\\"o_address_zip\\"/>\\n                                <div name=\\"partner_address_country\\" class=\\"d-flex justify-content-between\\">\\n                                    <field name=\\"country_id\\" placeholder=\\"Country\\" class=\\"o_address_country\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\"/>\\n                                </div>\\n                            </div>\\n                        </group>\\n                        <group>\\n                            <field name=\\"function\\" placeholder=\\"e.g. Sales Director\\" invisible=\\"is_company\\"/>\\n                            <field name=\\"vat\\" placeholder=\\"e.g. BE0477472701\\"/>\\n                            <field name=\\"website\\" string=\\"Website\\" widget=\\"url\\" placeholder=\\"e.g. https://www.odoo.com\\"/>\\n                            <field name=\\"lang\\" invisible=\\"active_lang_count &lt;= 1\\"/>\\n                            <field name=\\"category_id\\" widget=\\"many2many_tags\\" options=\\"{'color_field': 'color'}\\" placeholder=\\"e.g. &quot;B2B&quot;, &quot;VIP&quot;, &quot;Consulting&quot;, ...\\"/>\\n                        </group>\\n                    </group>\\n                    <div class=\\"d-flex\\">\\n                        <field name=\\"properties\\" nolabel=\\"1\\" columns=\\"2\\"/>\\n                    </div>\\n\\n                    <notebook colspan=\\"4\\">\\n                        <page string=\\"Contacts\\" nam