ompany_id)]\\" invisible=\\"move_type in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                        <field name=\\"invoice_cash_rounding_id\\" groups=\\"account.group_cash_rounding\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"invoice_source_email\\" widget=\\"email\\" invisible=\\"move_type not in ('in_invoice', 'in_refund') or not invoice_source_email\\"/>\\n                                        <field name=\\"auto_post\\" invisible=\\"move_type in ('out_receipt', 'in_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"auto_post_until\\" invisible=\\"auto_post in ('no', 'at_date')\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page id=\\"other_tab_entry\\" string=\\"Other Info\\" name=\\"other_info\\" invisible=\\"move_type != 'entry'\\">\\n                                <group id=\\"other_tab_entry_group\\">\\n                                    <group name=\\"misc_group\\">\\n                                        <field name=\\"auto_post\\" invisible=\\"move_type != 'entry'\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"reversed_entry_id\\" invisible=\\"move_type != 'entry' or not reversed_entry_id\\"/>\\n                                        <field name=\\"auto_post_until\\" invisible=\\"auto_post in ('no', 'at_date')\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"fiscal_position_id\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                        <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" required=\\"1\\"/>\\n                                    </group>\\n                                </group>\\n                                <!-- Internal note -->\\n                                <field name=\\"narration\\" placeholder=\\"Add an internal note...\\" nolabel=\\"1\\" height=\\"50\\"/>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                    <!-- Attachment preview -->\\n                    <div class=\\"o_attachment_preview\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund') or state != 'draft'\\"/>\\n                    <!-- Chatter -->\\n                    <chatter reload_on_attachment=\\"True\\"/>\\n                </form>", "es_ES": "<form string=\\"Asiento contable\\" js_class=\\"account_move_form\\">\\n                    <header>\\n                        <!-- Post -->\\n                        <button name=\\"action_post\\" string=\\"Publicar\\" class=\\"oe_highlight\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"q\\" context=\\"{'validate_analytic': True, 'disable_abnormal_invoice_detection': False}\\" invisible=\\"hide_post_button or move_type != 'entry'\\"/>\\n                        <button name=\\"action_post\\" string=\\"Confirmar\\" class=\\"oe_highlight\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"q\\" context=\\"{'validate_analytic': True, 'disable_abnormal_invoice_detection': False}\\" invisible=\\"hide_post_button or move_type == 'entry' or display_inactive_currency_warning\\"/>\\n                        <!-- Send (only invoices) -->\\n                        <button name=\\"action_invoice_sent\\" type=\\"object\\" string=\\"Enviar\\" invisible=\\"not display_send_button or not highlight_send_button\\" class=\\"oe_highlight\\" data-hotkey=\\"y\\"/>\\n                        <button name=\\"action_invoice_sent\\" type=\\"object\\" string=\\"Enviar\\" invisible=\\"not display_send_button or highlight_send_button\\" data-hotkey=\\"y\\"/>\\n                        <button name=\\"action_print_pdf\\" type=\\"object\\" class=\\"oe_highlight\\" invisible=\\"state != 'posted' or is_being_sent or invoice_pdf_report_id or move_type == 'entry'\\" string=\\"Imprimir\\"/>\\n                        <button name=\\"action_print_pdf\\" type=\\"object\\" invisible=\\"state != 'posted' or (not is_being_sent and not invoice_pdf_report_id)\\" string=\\"Imprimir\\"/>\\n                        <!-- Register Payment (only invoices / receipts) -->\\n                        <button name=\\"action_register_payment\\" id=\\"account_invoice_payment_btn\\" type=\\"object\\" class=\\"oe_highlight\\" invisible=\\"(                                     state != 'posted'                                     or payment_state not in ('not_paid', 'partial', 'in_payment')                                     or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')                                     or invoice_has_outstanding                                 )\\" context=\\"{'dont_redirect_to_payments': True, 'display_account_trust': True}\\" string=\\"Pagar\\" data-hotkey=\\"g\\" groups=\\"account.group_account_invoice\\"/>\\n                        <!-- Register Payment (only invoices / receipts, with outstanding payments) -->\\n                        <button name=\\"action_register_payment\\" id=\\"account_invoice_payment_secondary_btn\\" type=\\"object\\" invisible=\\"(                                     state != 'posted'                                     or payment_state not in ('not_paid', 'partial', 'in_payment')                                     or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')                                     or not invoice_has_outstanding                                 )\\" context=\\"{'dont_redirect_to_payments': True, 'display_account_trust': True}\\" string=\\"Pagar\\" data-hotkey=\\"g\\" groups=\\"account.group_account_invoice\\"/>\\n                        <!-- Preview (only customer invoices) -->\\n                        <button name=\\"preview_invoice\\" type=\\"object\\" string=\\"Vista previa\\" data-hotkey=\\"o\\" title=\\"Vista previa de la factura\\" invisible=\\"move_type not in ('out_invoice', 'out_refund') or state in ('draft', 'cancel')\\"/>\\n                        <!-- Reverse -->\\n                        <button name=\\"291\\" string=\\"Revertir asiento\\" type=\\"action\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"z\\" invisible=\\"move_type != 'entry' or state != 'posted' or payment_state == 'reversed'\\"/>\\n                        <button name=\\"action_reverse\\" string=\\"Factura rectificativa\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"move_type not in ('out_invoice', 'in_invoice') or state != 'posted'\\" data-hotkey=\\"shift+n\\"/>\\n                        <!-- Cancel -->\\n                        <button name=\\"button_cancel\\" string=\\"Cancelar asiento\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"x\\" invisible=\\"not id or state != 'draft' or move_type != 'entry'\\"/>\\n                        <button name=\\"button_cancel\\" string=\\"Cancelar\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"x\\" invisible=\\"not id or state != 'draft' or move_type == 'entry'\\"/>\\n                        <button name=\\"button_draft\\" string=\\"Restablecer a borrador\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"not show_reset_to_draft_button\\" data-hotkey=\\"r\\"/>\\n                        <button name=\\"button_hash\\" string=\\"Bloquear\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"not restrict_mode_hash_table or inalterable_hash or state != 'posted'\\"/>\\n                        <button string=\\"Solicitud de cancelación\\" name=\\"button_request_cancel\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"state != 'posted' or show_reset_to_draft_button or not need_cancel_request\\" data-hotkey=\\"w\\"/>\\n                        <!-- Review button -->\\n                        <button name=\\"button_set_checked\\" class=\\"btn btn-info\\" type=\\"object\\" string=\\"Revisado\\" invisible=\\"state != 'posted' or checked\\" groups=\\"account.group_account_user\\"/>\\n\\n                        <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,posted\\" groups=\\"!account.group_account_secured\\"/>\\n                        <field name=\\"state\\" widget=\\"account_move_statusbar_secured\\" statusbar_visible=\\"draft,posted\\" groups=\\"account.group_account_secured\\"/>\\n                    </header>\\n\\n                    <!-- General warnings computed from `_get_alerts` -->\\n                    <div class=\\"m-0\\" id=\\"alerts\\" invisible=\\"not alerts\\">\\n                        <field name=\\"alerts\\" class=\\"o_field_html\\" widget=\\"actionable_errors\\"/>\\n                    </div>\\n                    <!--Duplicate check-->\\n                    <div class=\\"alert alert-warning w-100 d-flex align-items-center gap-1\\" invisible=\\"not duplicated_ref_ids\\" role=\\"alert\\">\\n                        <span>This document might be a duplicate of</span>\\n                        <field name=\\"duplicated_ref_ids\\" widget=\\"x2many_buttons\\" string=\\"Documentos duplicados\\" context=\\"{'name_as_amount_total': True}\\"/>\\n                    </div>\\n                    <!-- Invoice outstanding credits -->\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"state != 'posted' or move_type not in ('out_invoice', 'out_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        Tiene <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">créditos pendientes</a></bold> que encuentra a continuación para este cliente.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"state != 'posted' or move_type not in ('in_invoice', 'in_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        Tiene <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">débitos pendientes</a></bold> que encuentra a continuación para este proveedor.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"state != 'posted' or move_type != 'out_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        Tiene <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">débitos pendientes</a></bold> que encuentra a continuación para este cliente.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"state != 'posted' or move_type != 'in_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        Tiene <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">créditos pendientes</a></bold> que encuentra a continuación para este proveedor.\\n                    </div>\\n                    <!-- Currency consistency -->\\n                    <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not display_inactive_currency_warning or move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\">\\n                        Para validar esta factura, debe <button class=\\"oe_link\\" type=\\"object\\" name=\\"action_activate_currency\\" style=\\"padding: 0; vertical-align: baseline;\\">activar la moneda de la factura</button>. Odoo debe calcular los asientos contables antes de contabilizarlas en la moneda de su empresa.\\n                    </div>\\n                    <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not display_inactive_currency_warning or move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\">\\n                        Para validar esta factura, debe <button class=\\"oe_link\\" type=\\"object\\" name=\\"action_activate_currency\\" style=\\"padding: 0; vertical-align: baseline;\\">activar la moneda de la factura</button>. Odoo debe calcular los asientos contables antes de contabilizarlas en la moneda de su empresa.\\n                    </div>\\n\\n                    <sheet>\\n                        <div name=\\"button_box\\" class=\\"oe_button_box\\">\\n                            <button name=\\"action_open_business_doc\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" type=\\"object\\" invisible=\\"move_type != 'entry' or not id or not origin_payment_id\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">1 pago</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_payments\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" type=\\"object\\" invisible=\\"not payment_count\\">\\n                                    <field name=\\"payment_count\\" string=\\"Pagos\\" widget=\\"statinfo\\"/>\\n                            </button>\\n                            <button name=\\"open_reconcile_view\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" type=\\"object\\" invisible=\\"move_type != 'entry' or not id or not has_reconciled_entries\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Apuntes conciliados</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_created_caba_entries\\" class=\\"oe_stat_button\\" icon=\\"fa-usd\\" type=\\"object\\" invisible=\\"not tax_cash_basis_created_move_ids\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Asientos del criterio de caja</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_adjusting_entries\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" type=\\"object\\" invisible=\\"not adjusting_entries_move_ids\\">\\n                                    <field name=\\"adjusting_entries_count\\" string=\\"Asientos de ajuste\\" widget=\\"statinfo\\"/>\\n                            </button>\\n                            <button name=\\"open_adjusting_entry_origin_moves\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" type=\\"object\\" invisible=\\"not adjusting_entry_origin_move_ids\\">\\n                                    <div invisible=\\"adjusting_entry_origin_moves_count != 1\\" class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">\\n                                            <field name=\\"adjusting_entry_origin_label\\"/>\\n                                        </span>\\n                                    </div>\\n                                    <field name=\\"adjusting_entry_origin_moves_count\\" invisible=\\"adjusting_entry_origin_moves_count == 1\\" string=\\"Facturas de clientes\\" widget=\\"statinfo\\"/>\\n                            </button>\\n                        </div>\\n\\n                        <widget name=\\"web_ribbon\\" title=\\"Enviado\\" bg_color=\\"gray_ribbon\\" invisible=\\"not is_move_sent or payment_state != 'not_paid' or move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                        <!-- Payment status for invoices / receipts -->\\n                        <widget name=\\"web_ribbon\\" title=\\"Enviado\\" bg_color=\\"text-bg-secondary\\" invisible=\\"status_in_payment != 'sent' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Pagada\\" invisible=\\"payment_state != 'paid' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"En proceso de pago\\" invisible=\\"payment_state != 'in_payment' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Parcial\\" bg_color=\\"text-bg-secondary\\" invisible=\\"payment_state != 'partial' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Revertido\\" invisible=\\"payment_state != 'reversed'\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Bloqueado\\" bg_color=\\"text-bg-danger\\" invisible=\\"payment_state != 'blocked' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                         <widget name=\\"web_ribbon\\" text=\\"Invoicing App Legacy\\" bg_color=\\"text-bg-info\\" invisible=\\"payment_state != 'invoicing_legacy'\\" tooltip=\\"This entry has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting.\\"/>\\n\\n                        <!-- Invisible fields -->\\n                        <field name=\\"id\\" invisible=\\"1\\"/>\\n                        <field name=\\"state\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"journal_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_name_warning\\" invisible=\\"1\\"/>\\n                        <field name=\\"posted_before\\" invisible=\\"1\\"/>\\n                        <!--test-tags .test_01_account_tour -->\\n                        <field name=\\"move_type\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                        <field name=\\"payment_state\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                        <field name=\\"invoice_filter_type_domain\\" invisible=\\"1\\"/>\\n                        <field name=\\"suitable_journal_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"currency_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                        <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"commercial_partner_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"bank_partner_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"display_qr_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_reset_to_draft_button\\" invisible=\\"1\\"/>\\n                        <field name=\\"expected_currency_rate\\" invisible=\\"1\\"/>\\n\\n                        <field name=\\"invoice_has_outstanding\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_move_sent\\" invisible=\\"1\\"/>\\n                        <field name=\\"invoice_pdf_report_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"need_cancel_request\\" invisible=\\"1\\"/>\\n                        <field name=\\"has_reconciled_entries\\" invisible=\\"1\\"/>\\n                        <field name=\\"restrict_mode_hash_table\\" invisible=\\"1\\"/>\\n                        <field name=\\"inalterable_hash\\" invisible=\\"1\\"/>\\n                        <field name=\\"country_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"display_inactive_currency_warning\\" invisible=\\"1\\"/>\\n                        <field name=\\"statement_line_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"statement_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"origin_payment_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_country_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_cash_basis_created_move_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"quick_edit_mode\\" invisible=\\"1\\"/>\\n                        <field name=\\"hide_post_button\\" invisible=\\"1\\"/>\\n                        <field name=\\"quick_encoding_vals\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_delivery_date\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_being_sent\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_update_fpos\\" invisible=\\"1\\"/>\\n\\n                        <div class=\\"oe_title\\">\\n                            <span class=\\"o_form_label\\">\\n                                <field name=\\"move_type\\" invisible=\\"move_type == 'entry'\\" widget=\\"receipt_selector\\" options=\\"{'horizontal': true}\\" nolabel=\\"1\\" readonly=\\"state != 'draft'\\"/>\\n                            </span>\\n\\n                            <div class=\\"text-warning\\" invisible=\\"not show_name_warning\\">El número más alto actual es <field class=\\"oe_inline\\" name=\\"highest_name\\"/>. Es posible que desee poner un número más alto aquí.</div>\\n\\n                            <h1>\\n                                <field name=\\"name\\" invisible=\\"not (name or name_placeholder or quick_edit_mode)\\" readonly=\\"state != 'draft'\\" options=\\"{'placeholder_field': 'name_placeholder'}\\"/>\\n\\n                                <span invisible=\\"name or name_placeholder or quick_edit_mode\\">Borrador</span>\\n                            </h1>\\n                        </div>\\n                        <group>\\n                            <group id=\\"header_left_group\\">\\n\\n                                <label for=\\"partner_id\\" string=\\"Cliente\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Proveedor\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                <div class=\\"o_col\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt', 'in_invoice', 'in_refund', 'in_receipt')\\">\\n                                    <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" nolabel=\\"1\\" context=\\"{                                             'res_partner_search_mode': (context.get('default_move_type', 'entry') in ('out_invoice', 'out_refund', 'out_receipt') and 'customer') or (context.get('default_move_type', 'entry') in ('in_invoice', 'in_refund', 'in_receipt') and 'supplier') or False,                                             'show_address': 1, 'default_is_company': True, 'show_vat': True}\\" domain=\\"[('company_id', 'in', (False, company_id))]\\" options=\\"{&quot;no_quick_create&quot;: True}\\" default_focus=\\"1\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" placeholder=\\"Buscar nombre o NIF...\\" readonly=\\"state != 'draft'\\"/>\\n                                    <button name=\\"action_update_fpos_values\\" type=\\"object\\" string=\\"Actualizar impuestos y cuentas\\" help=\\"Vuelva a calcular todos los impuestos y cuentas según la posición fiscal\\" class=\\"btn-link mb-1 px-0\\" icon=\\"fa-refresh\\" confirm=\\"Esto actualizará todos los impuestos y todas las cuentas según la posición fiscal actualmente establecida.\\" invisible=\\"not show_update_fpos or state in ['cancel', 'posted']\\"/>\\n                                </div>\\n\\n                                <field name=\\"partner_shipping_id\\" groups=\\"account.group_delivery_invoice_address\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"quick_edit_total_amount\\" class=\\"w-50\\" invisible=\\"move_type == 'entry' or not quick_edit_mode\\" readonly=\\"state != 'draft'\\"/>\\n                                <label for=\\"ref\\" string=\\"Referencia de factura\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt', 'in_refund')\\"/>\\n                                <field name=\\"ref\\" default_focus=\\"1\\" nolabel=\\"1\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt', 'in_refund')\\"/>\\n                                <field name=\\"ref\\" default_focus=\\"1\\" invisible=\\"move_type != 'entry'\\"/>\\n                                <field name=\\"tax_cash_basis_origin_move_id\\" invisible=\\"not tax_cash_basis_origin_move_id\\"/>\\n                                <label name=\\"invoice_vendor_bill_id_label\\" for=\\"invoice_vendor_bill_id\\" string=\\"Autocompletar\\" class=\\"oe_edit_only\\" invisible=\\"state != 'draft' or move_type not in ('in_invoice', 'in_refund')\\"/>\\n                                <field name=\\"invoice_vendor_bill_id\\" nolabel=\\"1\\" class=\\"oe_edit_only\\" invisible=\\"state != 'draft' or move_type not in ('in_invoice', 'in_refund')\\" domain=\\"[('company_id', '=', company_id), ('partner_id', 'child_of', [partner_id]), ('move_type', '=', move_type)]\\" placeholder=\\"Select an old purchase document\\" options=\\"{'no_create': True}\\" context=\\"{'show_total_amount': True}\\"/>\\n                            </group>\\n                            <group id=\\"header_right_group\\">\\n                                <label for=\\"invoice_date\\" string=\\"Fecha de factura\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                <field name=\\"invoice_date\\" nolabel=\\"1\\" options=\\"{'warn_future': true}\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\" readonly=\\"state != 'draft'\\" placeholder=\\"Hoy\\"/>\\n\\n                                <label for=\\"invoice_date\\" string=\\"Fecha de la factura\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                <field name=\\"invoice_date\\" nolabel=\\"1\\" options=\\"{'warn_future': true}\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" readonly=\\"state != 'draft'\\" placeholder=\\"Hoy\\"/>\\n\\n                                <field name=\\"date\\" string=\\"Fecha contable\\" invisible=\\"move_type in ('out_invoice', 'out_refund', 'out_receipt') and not quick_edit_mode and not (state == 'posted' and date != invoice_date)\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"payment_reference\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" readonly=\\"inalterable_hash != False\\" placeholder=\\"Usar referencia de factura\\"/>\\n                                <field name=\\"partner_bank_id\\" context=\\"{'default_partner_id': bank_partner_id, 'display_account_trust': True}\\" domain=\\"[('partner_id', '=', bank_partner_id)]\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" readonly=\\"is_move_sent and state != 'draft'\\"/>\\n\\n                                <!-- Invoice payment terms (only invoices) + due date (only invoices / receipts) -->\\n                                <div class=\\"o_td_label\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\">\\n                                    <label for=\\"invoice_date_due\\" string=\\"Fecha de vencimiento\\" invisible=\\"invoice_payment_term_id\\"/>\\n                                    <label for=\\"invoice_payment_term_id\\" string=\\"Condiciones de pago\\" invisible=\\"not invoice_payment_term_id\\"/>\\n                                </div>\\n                                <div class=\\"d-flex\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" name=\\"due_date\\">\\n                                    <field name=\\"invoice_date_due\\" force_save=\\"1\\" placeholder=\\"Fecha\\" invisible=\\"invoice_payment_term_id\\"/>\\n                                    <span class=\\"o_form_label mx-3 oe_edit_only text-center\\" style=\\"width: 6ch;\\" invisible=\\"state != 'draft' or invoice_payment_term_id\\">o</span>\\n                                    <field name=\\"invoice_payment_term_id\\" context=\\"{'example_date': invoice_date, 'example_amount': tax_totals['total_amount_currency']}\\" placeholder=\\"Condiciones de pago\\" options=\\"{'no_quick_create':True}\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                </div>\\n                                <field name=\\"taxable_supply_date_placeholder\\" invisible=\\"1\\"/> <!-- Needed for the placeholder widget -->\\n                                <field name=\\"taxable_supply_date\\" invisible=\\"not show_taxable_supply_date\\" readonly=\\"state != 'draft'\\" options=\\"{'placeholder_field': 'taxable_supply_date_placeholder'}\\"/>\\n                                <field name=\\"delivery_date\\" invisible=\\"not show_delivery_date\\" readonly=\\"state != 'draft'\\"/>\\n                                <label for=\\"journal_id\\" invisible=\\"not show_journal\\"/>\\n                                <label for=\\"currency_id\\" groups=\\"base.group_multi_currency\\" invisible=\\"show_journal\\"/>\\n                                <div name=\\"journal_div\\" class=\\"d-flex\\">\\n                                    <field name=\\"journal_id\\" invisible=\\"not show_journal\\" options=\\"{'no_create': True, 'no_open': True}\\" readonly=\\"posted_before and name not in (False, '', '/')\\"/>\\n                                    <div name=\\"in_and_refresh_button_div\\" groups=\\"base.group_multi_currency\\" class=\\"d-flex flex-column mx-3 text-center\\" style=\\"width: 6ch;\\" invisible=\\"move_type == 'entry'\\">\\n                                        <div>en</div>\\n                                        <div class=\\"d-flex flex-column justify-content-center flex-grow-1\\" invisible=\\"state != 'draft' or invoice_currency_rate == expected_currency_rate\\">\\n                                            <button type=\\"object\\" name=\\"refresh_invoice_currency_rate\\" icon=\\"fa-refresh\\" title=\\"Reset the currency rate to the default accordingly to the invoice date\\" class=\\"btn btn-link p-0\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <div name=\\"currency_div\\" groups=\\"base.group_multi_currency\\" class=\\"w-100\\" invisible=\\"move_type == 'entry'\\">\\n                                        <div class=\\"d-flex gap-1\\">\\n                                            <field name=\\"currency_id\\" readonly=\\"state != 'draft'\\" class=\\"oe_inline\\" options=\\"{'no_create': True}\\" context=\\"{'search_default_active': 1, 'search_default_inactive': 1}\\"/>\\n                                            <widget name=\\"account_pick_currency_date\\" invisible=\\"state != 'draft' or currency_id == company_currency_id\\"/>\\n                                        </div>\\n                                        <div name=\\"currency_conversion_div\\" class=\\"d-flex gap-1 text-muted\\" invisible=\\"currency_id == company_currency_id\\">\\n                                            <span>1</span>\\n                                            <field name=\\"company_currency_id\\" readonly=\\"True\\" options=\\"{'no_open': True}\\" class=\\"w-auto\\"/>\\n                                            <span>=</span>\\n                                            <field name=\\"invoice_currency_rate\\" digits=\\"[12,6]\\" readonly=\\"state != 'draft'\\"/>\\n                                            <field name=\\"currency_id\\" readonly=\\"True\\" options=\\"{'no_open': True}\\" class=\\"w-auto\\"/>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </group>\\n                        </group>\\n                        <notebook>\\n                            <page id=\\"invoice_tab\\" name=\\"invoice_tab\\" string=\\"Líneas de factura\\" invisible=\\"move_type == 'entry'\\">\\n                                <field name=\\"invoice_line_ids\\" widget=\\"product_label_section_and_note_field_o2m\\" mode=\\"list,kanban\\" context=\\"{                                            'default_move_type': context.get('default_move_type'),                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'default_display_type': 'product',                                            'quick_encoding_vals': quick_encoding_vals,                                        }\\" readonly=\\"state != 'draft'\\" aggregated_fields=\\"price_subtotal,price_total\\" options=\\"{