ent.move_type,                                                     'search_default_type_asset_fixed': 'in_' in parent.move_type,                                                     'search_default_type_expense': 'in_' in parent.move_type,                                                     'search_default_account_type': 'out_' in parent.move_type and 'income',                                                     'preferred_account_type': 'out_' in parent.move_type and 'income' or 'in_' in parent.move_type and 'expense',                                                }\\" groups=\\"account.group_account_readonly\\" options=\\"{'no_quick_create': True}\\" domain=\\"[('company_ids', 'parent_of', company_id), ('account_type', 'not in', ('asset_receivable', 'liability_payable', 'off_balance'))]\\" required=\\"display_type not in ('line_section', 'line_subsection', 'line_note')\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" string=\\"Analítico\\" groups=\\"analytic.group_analytic_accounting\\" optional=\\"show\\" options=\\"{'product_field': 'product_id', 'account_field': 'account_id', 'amount_field': 'price_subtotal'}\\" business_domain_compute=\\"parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'\\"/>\\n                                        <field name=\\"quantity\\" optional=\\"show\\"/>\\n                                        <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\" optional=\\"show\\" width=\\"92px\\" options=\\"{'no_create': True, 'quantity_field': 'quantity'}\\" widget=\\"many2one_uom\\"/>\\n                                        <!-- /l10n_in_edi.test_edi_json -->\\n                                        <!-- required for @api.onchange('product_id') -->\\n                                        <field name=\\"product_uom_id\\" column_invisible=\\"True\