ion\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\"/>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"price_subtotal\\" invisible=\\"parent.move_type not in ['in_invoice', 'in_refund', 'in_receipt'] and parent.company_price_include == 'tax_included'\\" string=\\"Importe\\"/>\\n                                                <field name=\\"price_total\\" invisible=\\"parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] or parent.company_price_include == 'tax_excluded'\\" string=\\"Importe\\"/>\\n                                            </group>\\n                                        </sheet>\\n                                    </form>\\n                                </field>\\n                                <group col=\\"12\\" class=\\"oe_invoice_lines_tab overflow-hidden\\">\\n                                    <group colspan=\\"8\\">\\n                                        <field name=\\"narration\\" placeholder=\\"Términos y condiciones\\" nolabel=\\"1\\"/>\\n                                    </group>\\n                                    <!-- Totals (only invoices / receipts) -->\\n                                    <group colspan=\\"4\\">\\n                                        <group class=\\"oe_subtotal_footer\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') or payment_state == 'invoicing_legacy'\\">\\n\\n                                            <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" colspan=\\"2\\" readonly=\\"state != 'draft' or (move_type not in ('in_invoice', 'in_refund', 'in_receipt') and not quick_edit_mode)\\"/>\\n\\n                                            <field name=\\"invoice_payments_widget\\" colspan=\\"2\\" nolabel=\\"1\\" widget=\\"payment