nt_id\\" required=\\"1\\" domain=\\"[('company_ids', 'parent_of', company_id)]\\"/>\\n                                        <field name=\\"partner_id\\" optional=\\"show\\" domain=\\"['|', ('parent_id', '=', False), ('is_company', '=', True)]\\" column_invisible=\\"parent.move_type != 'entry'\\"/>\\n                                        <field name=\\"name\\" widget=\\"section_and_note_text\\" optional=\\"show\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" optional=\\"show\\" options=\\"{'account_field': 'account_id'}\\" business_domain_compute=\\"parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'\\"/>\\n                                        <field name=\\"date_maturity\\" optional=\\"hide\\" column_invisible=\\"context.get('view_no_maturity')\\"/>\\n                                        <field name=\\"amount_currency\\" groups=\\"base.group_multi_currency\\" optional=\\"hide\\"/>\\n                                        <field name=\\"currency_id\\" options=\\"{'no_create': True}\\" optional=\\"hide\\" groups=\\"base.group_multi_currency\\" column_invisible=\\"parent.move_type != 'entry'\\"/>\\n                                        <field name=\\"tax_ids\\" widget=\\"autosave_many2many_tax_tags\\" optional=\\"hide\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id)]\\" context=\\"{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True                                                }\\" options=\\"{'no_create': True}\\" force_save=\\"1\\" readonly=\\"tax_line_id or (parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and account_type in ('asset_receivable', 'liability_payable'))\\"/>\\n                                        <field name=\\"debit\\" sum=\\"Débito total\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\" readonly=\\"parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('product')\\"/>\\n                                        <field name=\\"credit\\" sum=\\"Crédito total\\" invisible=\\"display_type in ('line_section', 'line_subsection', 'line_note')\\" readonly=\\"parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('product')\\"/>\\n                                        <field name=\\"balance\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"discount_date\\" string=\\"Fecha de descuento\\" optional=\\"hide\\"/>\\n                                        <field name=\\"discount_amount_currency\\" string=\\"Importe del descuento\\" optional=\\"hide\\"/>\\n\\n                                        <field name=\\"tax_tag_ids\\" widget=\\"many2many_tags\\" string=\\"Tablas de impuestos\\" optional=\\"show\\" options=\\"{'no_create': True}\\" domain=\\"[                                                     ('applicability', '=', 'taxes'),                                                     '|', ('country_id', '=', parent.tax_country_id),                                                     ('country_id', '=', False),                                                 ]\\"/>\\n\\n                                        <!-- Buttons -->\\n                                        <button name=\\"action_automatic_entry\\" type=\\"object\\" icon=\\"fa-calendar\\" string=\\"Cierre\\" aria-label=\\"Cambiar periodo\\" class=\\"float-end\\" column_invisible=\\"parent.move_type == 'entry' or parent.state != 'posted'\\" invisible=\\"account_internal_group not in ('income', 'expense')\\" context=\\"{'default_action': 'change_period'}\\"/>\\n\\n                                        <!-- Others fields -->\\n                                        <field name=\\"tax_line_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_currency_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"display_type\\" force_save=\\"1\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"sequence\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"account_internal_group\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"account_type\\" column_invisible=\\"True\\"/>\\n                                    </list>\\n                                    <!-- Form view to cover mobile use -->\\n                                    <form>\\n                                      <group>\\n                                        <field name=\\"account_id\\" domain=\\"[('company_ids', 'parent_of', company_id)]\\"/>\\n                                        <field name=\\"partner_id\\" domain=\\"['|', ('parent_id', '=', False), ('is_company', '=', True)]\\"/>\\n                                        <field name=\\"name\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\"/>\\n                                        <field name=\\"amount_currency\\" groups=\\"base.group_multi_currency\\"/>\\n                                        <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                        <field name=\\"currency_id\\" options=\\"{'no_create': True}\\" groups=\\"base.group_multi_currency\\"/>\\n                                        <field name=\\"debit\\" sum=\\"Débito total\\"/>\\n                                        <field name=\\"credit\\" sum=\\"Crédito total\\"/>\\n                                        <field name=\\"balance\\" invisible=\\"1\\"/>\\n                                        <field name=\\"tax_ids\\" string=\\"Impuestos aplicados\\" widget=\\"autosave_many2many_tax_tags\\" options=\\"{'no_create': True}\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id)]\\" context=\\"{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True,                                                }\\"/>\\n                                        <field name=\\"date_maturity\\" required=\\"0\\" invisible=\\"context.get('view_no_maturity', False)\\"/>\\n                                      </group>\\n                                    </form>\\n                                </field>\\n                                <div class=\\"alert alert-info text-center mb-0\\" role=\\"alert\\" invisible=\\"payment_state != 'invoicing_legacy' or move_type == 'entry'\\">\\n                                    <span>Este asiento se ha generado a través de la aplicación *Facturación*, antes de instalar *Contabilidad*. Su saldo se ha importado por separado.</span>\\n                                </div>\\n                            </page>\\n                            <page id=\\"other_tab\\" string=\\"Otra Información\\" name=\\"other_info\\" invisible=\\"move_type == 'entry'\\">\\n                                <group id=\\"other_tab_group\\">\\n                                    <group string=\\"Factura\\" name=\\"sale_info_group\\" invisible=\\"move_type not in ('out_invoice', 'out_refund')\\">\\n                                        <label for=\\"ref\\" string=\\"Referencia del cliente\\"/>\\n                                        <field name=\\"ref\\" nolabel=\\"1\\"/>\\n                                        <field name=\\"user_id\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                                        <field name=\\"invoice_user_id\\" domain=\\"[('share', '=', False)]\\" widget=\\"many2one_avatar_user\\"/>\\n                                        <field name=\\"invoice_origin\\" string=\\"Documento de origen\\" force_save=\\"1\\" invisible=\\"1\\"/>\\n                                        <field name=\\"partner_bank_id\\" context=\\"{'default_partner_id': bank_partner_id, 'display_account_trust': True}\\" domain=\\"[('partner_id.ref_company_ids', 'parent_of', company_id)]\\" readonly=\\"is_move_sent and state != 'draft'\\"/>\\n                                        <field name=\\"payment_reference\\" invisible=\\"move_type not in ('out_invoice', 'out_refund')\\" readonly=\\"inalterable_hash\\" placeholder=\\"Mensaje estándar\\"/>\\n                                        <field name=\\"qr_code_method\\" invisible=\\"not display_qr_code\\"/>\\n                                        <field name=\\"delivery_date\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                    <group string=\\"Contabilidad\\" name=\\"accounting_info_group\\">\\n                                        <field name=\\"company_id\\" groups=\\"base.group_multi_company\\"/>\\n                                        <field name=\\"invoice_incoterm_placeholder\\" invisible=\\"1\\"/>    <!-- Needed for placeholder_field -->\\n                                        <field name=\\"invoice_incoterm_id\\" options=\\"{'placeholder_field': 'invoice_incoterm_placeholder'}\\" invisible=\\"move_type in ('out_receipt', 'in_receipt')\\"/>\\n                                        <field name=\\"incoterm_location\\" invisible=\\"move_type in ('out_receipt', 'in_receipt')\\"/>\\n                                        <field name=\\"fiscal_position_id\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                        <field name=\\"secured\\" groups=\\"account.group_account_secured,base.group_no_one\\"/>\\n                                        <field name=\\"preferred_payment_method_line_id\\" string=\\"Método de pago\\" domain=\\"[('payment_type', '=', 'inbound'), ('company_id', '=', company_id)]\\" invisible=\\"move_type in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                        <field name=\\"preferred_payment_method_line_id\\" string=\\"Método de pago\\" domain=\\"[('payment_type', '=', 'outbound'), ('company_id', '=', company_id)]\\" invisible=\\"move_type in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                        <field name=\\"invoice_cash_rounding_id\\" groups=\\"account.group_cash_rounding\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"invoice_source_email\\" widget=\\"email\\" invisible=\\"move_type not in ('in_invoice', 'in_refund') or not invoice_source_email\\"/>\\n                                        <field name=\\"auto_post\\" invisible=\\"move_type in ('out_receipt', 'in_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"auto_post_until\\" invisible=\\"auto_post in ('no', 'at_date')\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page id=\\"other_tab_entry\\" string=\\"Otra Información\\" name=\\"other_info\\" invisible=\\"move_type != 'entry'\\">\\n                                <group id=\\"other_tab_entry_group\\">\\n                                    <group name=\\"misc_group\\">\\n                                        <field name=\\"auto_post\\" invisible=\\"move_type != 'entry'\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"reversed_entry_id\\" invisible=\\"move_type != 'entry' or not reversed_entry_id\\"/>\\n                                        <field name=\\"auto_post_until\\" invisible=\\"auto_post in ('no', 'at_date')\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"fiscal_position_id\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                        <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" required=\\"1\\"/>\\n                                    </group>\\n                                </group>\\n                                <!-- Internal note -->\\n                                <field name=\\"narration\\" placeholder=\\"Añada una nota interna...\\" nolabel=\\"1\\" height=\\"50\\"/>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                    <!-- Attachment preview -->\\n                    <div class=\\"o_attachment_preview\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund') or state != 'draft'\\"/>\\n                    <!-- Chatter -->\\n                    <chatter reload_on_attachment=\\"True\\"/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Account Entry" js_class="account_move_form">\n                    <header>\n                        <!-- Post -->\n                        <button name="action_post" string="Post" class="oe_highlight" type="object" groups="account.group_account_invoice" data-hotkey="q" context="{'validate_analytic': True, 'disable_abnormal_invoice_detection': False}" invisible="hide_post_button or move_type != 'entry'"/>\n                        <button name="action_post" string="Confirm" class="oe_highlight" type="object" groups="account.group_account_invoice" data-hotkey="q" context="{'validate_analytic': True, 'disable_abnormal_invoice_detection': False}" invisible="hide_post_button or move_type == 'entry' or display_inactive_currency_warning"/>\n                        <!-- Send (only invoices) -->\n                        <button name="action_invoice_sent" type="object" string="Send" invisible="not display_send_button or not highlight_send_button" class="oe_highlight" data-hotkey="y"/>\n                        <button name="action_invoice_sent" type="object" string="Send" invisible="not display_send_button or highlight_send_button" data-hotkey="y"/>\n                        <button name="action_print_pdf" type="object" class="oe_highlight" invisible="state != 'posted' or is_being_sent or invoice_pdf_report_id or move_type == 'entry'" string="Print"/>\n                        <button name="action_print_pdf" type="object" invisible="state != 'posted' or (not is_being_sent and not invoice_pdf_report_id)" string="Print"/>\n                        <!-- Register Payment (only invoices / receipts) -->\n                        <button name="action_register_payment" id="account_invoice_payment_btn" type="object" class="oe_highlight" invisible="(                                     state != 'posted'                                     or payment_state not in ('not_paid', 'partial', 'in_payment')                                     or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')                                     or invoice_has_outstanding                                 )" context="{'dont_redirect_to_payments': True, 'display_account_trust': True}" string="Pay" data-hotkey="g" groups="account.group_account_invoice"/>\n                        <!-- Register Payment (only invoices / receipts, with outstanding payments) -->\n                        <button name="action_register_payment" id="account_invoice_payment_secondary_btn" type="object" invisible="(                                     state != 'posted'                                     or payment_state not in ('not_paid', 'partial', 'in_payment')                                     or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')                                     or not invoice_has_outstanding                                 )" context="{'dont_redirect_to_payments': True, 'display_account_trust': True}" string="Pay" data-hotkey="g" groups="account.group_account_invoice"/>\n                        <!-- Preview (only customer invoices) -->\n                        <button name="preview_invoice" type="object" string="Preview" data-hotkey="o" title="Preview invoice" invisible="move_type not in ('out_invoice', 'out_refund') or state in ('draft', 'cancel')"/>\n                        <!-- Reverse -->\n                        <button name="291" string="Reverse Entry" type="action" groups="account.group_account_invoice" data-hotkey="z" invisible="move_type != 'entry' or state != 'posted' or payment_state == 'reversed'"/>\n                        <button name="action_reverse" string="Credit Note" type="object" groups="account.group_account_invoice" invisible="move_type not in ('out_invoice', 'in_invoice') or state != 'posted'" data-hotkey="shift+n"/>\n                        <!-- Cancel -->\n                        <button name="button_cancel" string="Cancel Entry" type="object" groups="account.group_account_invoice" data-hotkey="x" invisible="not id or state != 'draft' or move_type != 'entry'"/>\n                        <button name="button_cancel" string="Cancel" type="object" groups="account.group_account_invoice" data-hotkey="x" invisible="not id or state != 'draft' or move_type == 'entry'"/>\n                        <button name="button_draft" string="Reset to Draft" type="object" groups="account.group_account_invoice" invisible="not show_reset_to_draft_button" data-hotkey="r"/>\n                        <button name="button_hash" string="Lock" type="object" groups="account.group_account_invoice" invisible="not restrict_mode_hash_table or inalterable_hash or state != 'posted'"/>\n                        <button string="Request Cancel" name="button_request_cancel" type="object" groups="account.group_account_invoice" invisible="state != 'posted' or show_reset_to_draft_button or not need_cancel_request" data-hotkey="w"/>\n                        <!-- Review button -->\n                        <button name="button_set_checked" class="btn btn-info" type="object" string="Reviewed" invisible="state != 'posted' or checked" groups="account.group_account_user"/>\n\n                        <field name="state" widget="statusbar" statusbar_visible="draft,posted" groups="!account.group_account_secured"/>\n                        <field name="state" widget="account_move_statusbar_secured" statusbar_visible="draft,posted" groups="account.group_account_secured"/>\n                    </header>\n\n                    <!-- General warnings computed from `_get_alerts` -->\n                    <div class="m-0" id="alerts" invisible="not alerts">\n                        <field name="alerts" class="o_field_html" widget="actionable_errors"/>\n                    </div>\n                    <!--Duplicate check-->\n                    <div class="alert alert-warning w-100 d-flex align-items-center gap-1" invisible="not duplicated_ref_ids" role="alert">\n                        <span>This document might be a duplicate of</span>\n                        <field name="duplicated_ref_ids" widget="x2many_buttons" string="Duplicated Documents" context="{'name_as_amount_total': True}"/>\n                    </div>\n                    <!-- Invoice outstanding credits -->\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="state != 'posted' or move_type not in ('out_invoice', 'out_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding credits</a></bold> listed below for this customer.\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="state != 'posted' or move_type not in ('in_invoice', 'in_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding debits</a></bold> listed below for this vendor.\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="state != 'posted' or move_type != 'out_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding debits</a></bold> listed below for this customer.\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="state != 'posted' or move_type != 'in_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding credits</a></bold> listed below for this vendor.\n                    </div>\n                    <!-- Currency consistency -->\n                    <div class="alert alert-warning" role="alert" invisible="not display_inactive_currency_warning or move_type not in ('in_invoice', 'in_refund', 'in_receipt')">\n                        In order to validate this bill, you must <button class="oe_link" type="object" name="action_activate_currency" style="padding: 0; vertical-align: baseline;">activate the currency of the bill</button>. The journal entries need to be computed by Odoo before being posted in your company's currency.\n                    </div>\n                    <div class="alert alert-warning" role="alert" invisible="not display_inactive_currency_warning or move_type not in ('out_invoice', 'out_refund', 'out_receipt')">\n                        In order to validate this invoice, you must <button class="oe_link" type="object" name="action_activate_currency" style="padding: 0; vertical-align: baseline;">activate the currency of the invoice</button>. The journal entries need to be computed by Odoo before being posted in your company's currency.\n                    </div>\n\n                    <sheet>\n                        <div name="button_box" class="oe_button_box">\n                            <button name="action_open_business_doc" class="oe_stat_button" icon="fa-bars" type="object" invisible="move_type != 'entry' or not id or not origin_payment_id">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">1 Payment</span>\n                                    </div>\n                            </button>\n                            <button name="open_payments" class="oe_stat_button" icon="fa-bars" type="object" invisible="not payment_count">\n                                    <field name="payment_count" string="Payments" widget="statinfo"/>\n                            </button>\n                            <button name="open_reconcile_view" class="oe_stat_button" icon="fa-bars" type="object" invisible="move_type != 'entry' or not id or not has_reconciled_entries">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">Reconciled Items</span>\n                                    </div>\n                            </button>\n                            <button name="open_created_caba_entries" class="oe_stat_button" icon="fa-usd" type="object" invisible="not tax_cash_basis_created_move_ids">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">Cash Basis Entries</span>\n                                    </div>\n                            </button>\n                            <button name="open_adjusting_entries" class="oe_stat_button" icon="fa-bars" type="object" invisible="not adjusting_entries_move_ids">\n                                    <field name="adjusting_entries_count" string="Adjusting Entries" widget="statinfo"/>\n                            </button>\n                            <button name="open_adjusting_entry_origin_moves" class="oe_stat_button" icon="fa-bars" type="object" invisible="not adjusting_entry_origin_move_ids">\n                                    <div invisible="adjusting_entry_origin_moves_count != 1" class="o_stat_info">\n                                        <span class="o_stat_text">\n                                            <field name="adjusting_entry_origin_label"/>\n                                        </span>\n                                    </div>\n                                    <field name="adjusting_entry_origin_moves_count" invisible="adjusting_entry_origin_moves_count == 1" string="Invoices" widget="statinfo"/>\n                            </button>\n                        </div>\n\n                        <widget name="web_ribbon" title="Sent" bg_color="gray_ribbon" invisible="not is_move_sent or payment_state != 'not_paid' or move_type not in ('out_invoice', 'out_refund', 'out_receipt')"/>\n                        <!-- Payment status for invoices / receipts -->\n                        <widget name="web_ribbon" title="Sent" bg_color="text-bg-secondary" invisible="status_in_payment != 'sent' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="Paid" invisible="payment_state != 'paid' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="In Payment" invisible="payment_state != 'in_payment' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="Partial" bg_color="text-bg-secondary" invisible="payment_state != 'partial' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="Reversed" invisible="payment_state != 'reversed'"/>\n                        <widget name="web_ribbon" title="Blocked" bg_color="text-bg-danger" invisible="payment_state != 'blocked' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                         <widget name="web_ribbon" text="Invoicing App Legacy" bg_color="text-bg-info" invisible="payment_state != 'invoicing_legacy'" tooltip="This entry has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting."/>\n\n                        <!-- Invisible fields -->\n                        <field name="id" invisible="1"/>\n                        <field name="state" invisible="1"/>\n                        <field name="company_id" invisible="1"/>\n                        <field name="journal_id" invisible="1"/>\n                        <field name="show_name_warning" invisible="1"/>\n                        <field name="posted_before" invisible="1"/>\n                        <!--test-tags .test_01_account_tour -->\n                        <field name="move_type" invisible="1" force_save="1"/>\n                        <field name="payment_state" invisible="1" force_save="1"/>\n                        <field name="invoice_filter_type_domain" invisible="1"/>\n                        <field name="suitable_journal_ids" invisible="1"/>\n                        <field name="currency_id" invisible="1" readonly="state in ['cancel', 'posted']"/>\n                        <field name="company_currency_id" invisible="1"/>\n                        <field name="commercial_partner_id" invisible="1"/>\n                        <field name="bank_partner_id" invisible="1"/>\n                        <field name="display_qr_code" invisible="1"/>\n                        <field name="show_reset_to_draft_button" invisible="1"/>\n                        <field name="expected_currency_rate" invisible="1"/>\n\n                        <field name="invoice_has_outstanding" invisible="1"/>\n                        <field name="is_move_sent" invisible="1"/>\n                        <field name="invoice_pdf_report_id" invisible="1"/>\n                        <field name="need_cancel_request" invisible="1"/>\n                        <field name="has_reconciled_entries" invisible="1"/>\n                        <field name="restrict_mode_hash_table" invisible="1"/>\n                        <field name="inalterable_hash" invisible="1"/>\n                        <field name="country_code" invisible="1"/>\n                        <field name="display_inactive_currency_warning" invisible="1"/>\n                        <field name="statement_line_id" invisible="1"/>\n                        <field name="statement_id" invisible="1"/>\n                        <field name="origin_payment_id" invisible="1"/>\n                        <field name="tax_country_id" invisible="1"/>\n                        <field name="tax_calculation_rounding_method" invisible="1"/>\n                        <field name="tax_cash_basis_created_move_ids" invisible="1"/>\n                        <field name="quick_edit_mode" invisible="1"/>\n                        <field name="hide_post_button" invisible="1"/>\n                        <field name="quick_encoding_vals" invisible="1"/>\n                        <field name="show_delivery_date" invisible="1"/>\n                        <field name="is_being_sent" invisible="1"/>\n                        <field name="show_update_fpos" invisible="1"/>\n\n                        <div class="oe_title">\n                            <span class="o_form_label">\n                                <field name="move_type" invisible="move_type == 'entry'" widget="receipt_selector" options="{'horizontal': true}" nolabel="1" readonly="state != 'draft'"/>\n                            </span>\n\n                            <div class="text-warning" invisible="not show_name_warning">The current highest number is <field class="oe_inline" name="highest_name"/>. You might want to put a higher number here.</div>\n\n                            <h1>\n                                <field name="name" invisible="not (name or name_placeholder or quick_edit_mode)" readonly="state != 'draft'" options="{'placeholder_field': 'name_placeholder'}"/>\n\n                                <span invisible="name or name_placeholder or quick_edit_mode">Draft</span>\n                            </h1>\n                        </div>\n                        <group>\n                            <group id="header_left_group">\n\n                                <label for="partner_id" string="Customer" style="font-weight:bold;" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')"/>\n                                <label for="partner_id" string="Vendor" style="font-weight:bold;" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')"/>\n                                <div class="o_col" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt', 'in_invoice', 'in_refund', 'in_receipt')">\n                                    <field name="partner_id" widget="res_partner_many2one" nolabel="1" context="{                                             'res_partner_search_mode': (context.get('default_move_type', 'entry') in ('out_invoice', 'out_refund', 'out_receipt') and 'customer') or (context.get('default_move_type', 'entry') in ('in_invoice', 'in_refund', 'in_receipt') and 'supplier') or False,                                             'show_address': 1, 'default_is_company': True, 'show_vat': True}" domain="[('company_id', 'in', (False, company_id))]" options="{&quot;no_quick_create&quot;: True}" default_focus="1" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')" placeholder="Search a name or Tax ID..." readonly="state != 'draft'"/>\n                                    <button name="action_update_fpos_values" type="object" string="Update Taxes and Accounts" help="Recompute all taxes and accounts based on this fiscal position" class="btn-link mb-1 px-0" icon="fa-refresh" confirm="This will update all taxes and accounts based on the currently selected fiscal position." invisible="not show_update_fpos or state in ['cancel', 'posted']"/>\n                                </div>\n\n                                <field name="partner_shipping_id" groups="account.group_delivery_invoice_address" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')" readonly="state != 'draft'"/>\n                                <field name="quick_edit_total_amount" class="w-50" invisible="move_type == 'entry' or not quick_edit_mode" readonly="state != 'draft'"/>\n                                <label for="ref" string="Bill Reference" invisible="move_type not in ('in_invoice', 'in_receipt', 'in_refund')"/>\n                                <field name="ref" default_focus="1" nolabel="1" invisible="move_type not in ('in_invoice', 'in_receipt', 'in_refund')"/>\n                                <field name="ref" default_focus="1" invisible="move_type != 'entry'"/>\n                                <field name="tax_cash_basis_origin_move_id" invisible="not tax_cash_basis_origin_move_id"/>\n                                <label name="invoice_vendor_bill_id_label" for="invoice_vendor_bill_id" string="Auto-Complete" class="oe_edit_only" invisible="state != 'draft' or move_type not in ('in_invoice', 'in_refund')"/>\n                                <field name="invoice_vendor_bill_id" nolabel="1" class="oe_edit_only" invisible="state != 'draft' or move_type not in ('in_invoice', 'in_refund')" domain="[('company_id', '=', company_id), ('partner_id', 'child_of', [partner_id]), ('move_type', '=', move_type)]" placeholder="Select an old purchase document" options="{'no_create': True}" context="{'show_total_amount': True}"/>\n                            </group>\n                            <group id="header_right_group">\n                                <label for="invoice_date" string="Invoice Date" style="font-weight:bold;" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')"/>\n                                <field name="invoice_date" nolabel="1" options="{'warn_future': true}" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')" readonly="state != 'draft'" placeholder="Today"/>\n\n                                <label for="invoice_date" string="Bill Date" style="font-weight:bold;" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')"/>\n                                <field name="invoice_date" nolabel="1" options="{'warn_future': true}" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')" readonly="state != 'draft'" placeholder="Today"/>\n\n                                <field name="date" string="Accounting Date" invisible="move_type in ('out_invoice', 'out_refund', 'out_receipt') and not quick_edit_mode and not (state == 'posted' and date != invoice_date)" readonly="state != 'draft'"/>\n                                <field name="payment_reference" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')" readonly="inalterable_hash != False" placeholder="Use Bill Reference"/>\n                                <field name="partner_bank_id" context="{'default_partner_id': bank_partner_id, 'display_account_trust': True}" domain="[('partner_id', '=', bank_partner_id)]" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')" readonly="is_move_sent and state != 'draft'"/>\n\n                                <!-- Invoice payment terms (only invoices) + due date (only invoices / receipts) -->\n                                <div class="o_td_label" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')">\n                                    <label for="invoice_date_due" string="Due Date" invisible="invoice_payment_term_id"/>\n                                    <label for="invoice_payment_term_id" string="Payment terms" invisible="not invoice_payment_term_id"/>\n                                </div>\n                                <div class="d-flex" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')" name="due_date">\n                                    <field name="invoice_date_due" force_save="1" placeholder="Date" invisible="invoice_payment_term_id"/>\n                                    <span class="o_form_label mx-3 oe_edit_only text-center" style="width: 6ch;" invisible="state != 'draft' or invoice_payment_term_id">or</span>\n                                    <field name="invoice_payment_term_id" context="{'example_date': invoice_date, 'example_amount': tax_totals['total_amount_currency']}" placeholder="Payment Terms" options="{'no_quick_create':True}" readonly="state in ['cancel', 'posted']"/>\n                                </div>\n                                <field name="taxable_supply_date_placeholder" invisible="1"/> <!-- Needed for the placeholder widget -->\n                                <field name="taxable_supply_date" invisible="not show_taxable_supply_date" readonly="state != 'draft'" options="{'placeholder_field': 'taxable_supply_date_placeholder'}"/>\n                                <field name="delivery_date" invisible="not show_delivery_date" readonly="state != 'draft'"/>\n                                <label for="journal_id" invisible="not show_journal"/>\n                                <label for="currency_id" groups="base.group_multi_currency" invisible="show_journal"/>\n                                <div name="journal_div" class="d-flex">\n                                    <field name="journal_id" invisible="not show_journal" options="{'no_create': True, 'no_open': True}" readonly="posted_before and name not in (False, '', '/')"/>\n                                    <div name="in_and_refresh_button_div" groups="base.group_multi_currency" class="d-flex flex-column mx-3 text-center" style="width: 6ch;" invisible="move_type == 'entry'">\n                                        <div>in</div>\n                                        <div class="d-flex flex-column justify-content-center flex-grow-1" invisible="state != 'draft' or invoice_currency_rate == expected_currency_rate">\n                                            <button type="object" name="refresh_invoice_currency_rate" icon="fa-refresh" title="Reset the currency rate to the default accordingly to the invoice date" class="btn btn-link p-0"/>\n                                        </div>\n                                    </div>\n                                    <div name="currency_div" groups="base.group_multi_currency" class="w-100" invisible="move_type == 'entry'">\n                                        <div class="d-flex gap-1">\n                                            <field name="currency_id" readonly="state != 'draft'" class="oe_inline" options="{'no_create': True}" context="{'search_default_active': 1, 'search_default_inactive': 1}"/>\n                                            <widget name="account_pick_currency_date" invisible="state != 'draft' or currency_id == company_currency_id"/>\n                                        </div>\n                                        <div name="currency_conversion_div" class="d-flex gap-1 text-muted" invisible="currency_id == company_currency_id">\n                                            <span>1</span>\n                                            <field name="company_currency_id" readonly="True" options="{'no_open': True}" class="w-auto"/>\n                                            <span>=</span>\n                                            <field name="invoice_currency_rate" digits="[12,6]" readonly="state != 'draft'"/>\n                                            <field name="currency_id" readonly="True" options="{'no_open': True}" class="w-auto"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </group>\n                        </group>\n                        <notebook>\n                            <page id="invoice_tab" name="invoice_tab" string="Invoice Lines" invisible="move_type == 'entry'">\n                                <field name="invoice_line_ids" widget="product_label_section_and_note_field_o2m" mode="list,kanban" context="{                                            'default_move_type': context.get('default_move_type'),                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'default_display_type': 'product',                                            'quick_encoding_vals': quick_encoding_vals,                                        }" readonly="state != 'draft'" aggregated_fields="price_subtotal,price_total" options="{'hide_composition': True, 'hide_prices': True, 'subsections': True}">\n                                    <list name="journal_items" editable="bottom" string="Journal Items" default_order="sequence, id">\n                                        <control>\n                                            <create name="add_line_control" string="Add a line"/>\n                                            <create name="add_section_control" string="Add a section" context="{'default_display_type': 'line_section'}"/>\n                                            <create name="add_note_control" string="Add a note" context="{'default_display_type': 'line_note'}"/>\n                                            <button name="action_add_from_catalog" string="Catalog" type="object" class="btn-link" context="{'order_id': parent.id}"/>\n                                        </control>\n\n                                        <!-- Displayed fields -->\n                                        <field name="sequence" widget="handle"/>\n                                        <field name="product_id" optional="conditional" widget="product_label_section_and_note_field" domain="                                                     context.get('default_move_type') in ('out_invoice', 'out_refund', 'out_receipt')                                                     and [('sale_ok', '=', True)]                                                     or [('purchase_ok', '=', True)]                                                "/>\n                                        <field name="name" widget="section_and_note_text" optional="show"/>\n                                        <field name="account_id" context="{                                                     'partner_id': partner_id,                                                     'move_type': parent.move_type,                                                     'search_default_type_asset_fixed': 'in_' in parent.move_type,                                                     'search_default_type_expense': 'in_' in parent.move_type,                                                     'search_default_account_type': 'out_' in parent.move_type and 'income',                                                     'preferred_account_type': 'out_' in parent.move_type and 'income' or 'in_' in parent.move_type and 'expense',                                                }" groups="account.group_account_readonly" options="{'no_quick_create': True}" domain="[('company_ids', 'parent_of', company_id), ('account_type', 'not in', ('asset_receivable', 'liability_payable', 'off_balance'))]" required="display_type not in ('line_section', 'line_subsection', 'line_note')"/>\n                                        <field name="analytic_distribution" widget="analytic_distribution" string="Analytic" groups="analytic.group_analytic_accounting" optional="show" options="{'product_field': 'product_id', 'account_field': 'account_id', 'amount_field': 'price_subtotal'}" business_domain_compute="parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'"/>\n                                        <field name="quantity" optional="show"/>\n                                        <field name="product_uom_id" groups="uom.group_uom" optional="show" width="92px" options="{'no_create': True, 'quantity_field': 'quantity'}" widget="many2one_uom"/>\n                                        <!-- /l10n_in_edi.test_edi_json -->\n                                        <!-- required for @api.onchange('product_id') -->\n                                        <field name="product_uom_id" column_invisible="True"/>\n                                        <field name="price_unit" string="Price"/>\n                                        <field name="discount" width="50px" string="Disc.%" optional="hide"/>\n                                        <field name="tax_ids" widget="many2many_tax_tags" domain="[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]" context="{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True,                                                     'dynamic_fiscal_position_id': parent.fiscal_position_id,                                                }" options="{'no_create': True}" optional="show"/>\n                                        <field name="deductible_amount" column_invisible="parent.move_type not in ('in_invoice', 'in_refund')" string="Professional %" optional="hide" groups="!account.group_partial_purchase_deductibility"/>\n                                        <field name="deductible_amount" column_invisible="parent.move_type not in ('in_invoice', 'in_refund')" string="Professional %" optional="show" groups="account.group_partial_purchase_deductibility"/>\n                                        <field name="price_subtotal" column_invisible="parent.move_type not in ['in_invoice', 'in_refund', 'in_receipt'] and parent.company_price_include == 'tax_included'" string="Amount"/>\n                                        <field name="price_total" column_invisible="parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] or parent.company_price_include == 'tax_excluded'" string="Amount"/>\n                                        <!-- Others fields -->\n                                        <field name="partner_id" column_invisible="True"/>\n                                        <field name="currency_id" column_invisible="True"/>\n                                        <field name="company_id" column_invisible="True"/>\n                                        <field name="company_currency_id" column_invisible="True"/>\n                                        <field name="display_type" force_save="1" column_invisible="True"/>\n                                        <field name="collapse_prices" column_invisible="True"/>\n                                        <field name="collapse_composition" column_invisible="True"/>\n                                    </list>\n                                    <kanban class="o_kanban_mobile">\n                                        <!-- Displayed fields -->\n                                        <templates>\n                                            <t t-name="card">\n                                                <div t-attf-class="ps-0 pe-0 {{ record.display_type.raw_value ? 'o_is_' + record.display_type.raw_value : '' }}">\n                                                    <t t-if="!['line_note', 'line_section', 'line_subsection'].includes(record.display_type.raw_value)">\n                                                        <div class="row g-0">\n                                                            <div class="col-2 pe-3">\n                                                                <field name="product_id" widget="image" options="{'preview_image': 'image_128'}" class="w-100"/>\n                                                            </div>\n                                                            <div class="col-10">\n                                                                <div class="row">\n                                                                    <div class="col">\n                                                                        <field class="fw-bold" name="product_id"/>\n                                                                    </div>\n                                                                    <div class="col-auto fw-bold float-end text-end">\n                                                                        <field name="price_subtotal" t-if="['in_invoice', 'in_refund', 'in_receipt'].includes(record.move_type.raw_value)" string="Amount"/>\n                                                                        <field name="price_total" t-if="!['in_invoice', 'in_refund', 'in_receipt'].includes(record.move_type.raw_value)" string="Amount"/>\n                                                                    </div>\n                                                                </div>\n                                                                <div class="text-muted">\n                                                                    Quantity:\n                                                                    <field name="quantity"/>\n                                                                    <field name="product_uom_id" groups="uom.group_uom" widget="many2one_uom"/>\n                                                                </div>\n                                                                <div class="text-muted">\n                                                                    Unit Price:\n                                                                    <field name="price_unit"/>\n                                                                </div>\n                                                            </div>\n                                                        </div>\n                                                    </t>\n                                                    <t t-if="['line_section', 'line_subsection', 'line_note'].includes(record.display_type.raw_value)">\n                                                        <div t-att-class="{                                                             'fw-bolder': record.display_type.raw_value === 'line_section',                                                             'fw-bold': record.display_type.raw_value === 'line_subsection',                                                             'fst-italic': record.display_type.raw_value === 'line_note',                                                         }">\n                                                            <field name="name"/>\n                                                        </div>\n                                                    </t>\n                                                </div>\n                                            </t>\n                                        </templates>\n\n                                        <!-- Others fields -->\n                                        <field name="tax_calculation_rounding_method"/>\n                                        <field name="currency_id"/>\n                                        <field name="company_currency_id"/>\n                                        <field name="display_type" force_save="1"/>\n                                        <field name="move_type"/>\n                                    </kanban>\n\n                                    <!-- Form view to cover mobile use -->\n                                    <form>\n                                        <sheet>\n                                            <field name="tax_calculation_rounding_method" invisible="1"/>\n                                            <field name="display_type" invisible="1"/>\n                                            <field name="company_id" invisible="1"/>\n                                            <field name="partner_id" invisible="1"/>\n                                            <group>\n                                                <field name="product_id" widget="many2one_barcode"/>\n                                                <label for="name" string="Description" invisible="display_type in ('line_section', 'line_subsection', 'line_note')"/>\n                                                <label for="name" string="Section" invisible="display_type != 'line_section'"/>\n                                                <label for="name" string="Subsection" invisible="display_type != 'line_subsection'"/>\n                                                <label for="name" string="Note" invisible="display_type != 'line_note'"/>\n                                                <field name="name" widget="text" nolabel="1"/>\n                                                <field name="quantity"/>\n                                                <field name="product_uom_id" groups="uom.group_uom" widget="many2one_uom"/>\n                                                <field name="price_unit"/>\n                                                <field name="discount" string="Disc.%"/>\n                                            </group>\n                                            <group>\n                                                <field name="account_id" domain="[('company_ids', 'parent_of', company_id)]" options="{'no_create': True}" context="{'partner_id': partner_id, 'move_type': parent.move_type}"/>\n                                                <field name="tax_ids" widget="many2many_tax_tags"/>\n                                                <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting"/>\n                                            </group>\n                                            <group>\n                                                <field name="price_subtotal" invisible="parent.move_type not in ['in_invoice', 'in_refund', 'in_receipt'] and parent.company_price_include == 'tax_included'" string="Amount"/>\n                                                <field name="price_total" invisible="parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] or parent.company_price_include == 'tax_excluded'" string="Amount"/>\n                                            </group>\n                                        </sheet>\n                                    </form>\n                                </field>\n                                <group col="12" class="oe_invoice_lines_tab overflow-hidden">\n                                    <group colspan="8">\n                                        <field name="narration" placeholder="Terms and Conditions" nolabel="1"/>\n                                    </group>\n                                    <!-- Totals (only invoices / receipts) -->\n                                    <group colspan="4">\n                                        <group class="oe_subtotal_footer" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') or payment_state == 'invoicing_legacy'">\n\n                                            <field name="tax_totals" widget="account-tax-totals-field" nolabel="1" colspan="2" readonly="state != 'draft' or (move_type not in ('in_invoice', 'in_refund', 'in_receipt') and not quick_edit_mode)"/>\n\n                                            <field name="invoice_payments_widget" colspan="2" nolabel="1" widget="payment"/>\n                                            <field name="amount_residual" class="oe_subtotal_footer_separator"/>\n                                        </group>\n                                        <group class="oe_subtotal_footer px-4" invisible="state != 'posted' or not invoice_has_outstanding" groups="account.group_account_invoice,account.group_account_readonly">\n                                            <field name="invoice_outstanding_credits_debits_widget" class="oe_invoice_outstanding_credits_debits py-3" colspan="2" nolabel="1" widget="payment"/>\n                                        </group>\n                                    </group>\n                                </group>\n                            </page>\n                            <page id="aml_tab" string="Journal Items" groups="account.group_account_readonly" name="aml_tab">\n                                <field name="journal_line_ids" mode="list,kanban" context="{                                            'default_move_type': context.get('default_move_type'),                                            'line_ids': line_ids,                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'kanban_view_ref': 'account.account_move_line_view_kanban_mobile',                                        }" invisible="payment_state == 'invoicing_legacy' and move_type != 'entry'" readonly="state != 'draft'">\n                                    <list editable="bottom" string="Journal Items" default_order="sequence, id">\n                                        <!-- Displayed fields -->\n                                        <field name="account_id" required="1" domain="[('company_ids', 'parent_of', company_id)]"/>\n                                        <field name="partner_id" optional="show" domain="['|', ('parent_id', '=', False), ('is_company', '=', True)]" column_invisible="parent.move_type != 'entry'"/>\n                                        <field name="name" widget="section_and_note_text" optional="show"/>\n                                        <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" optional="show" options="{'account_field': 'account_id'}" business_domain_compute="parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'"/>\n                                        <field name="date_maturity" optional="hide" column_invisible="context.get('view_no_maturity')"/>\n                                        <field name="amount_currency" groups="base.group_multi_currency" optional="hide"/>\n                                        <field name="currency_id" options="{'no_create': True}" optional="hide" groups="base.group_multi_currency" column_invisible="parent.move_type != 'entry'"/>\n                                        <field name="tax_ids" widget="autosave_many2many_tax_tags" optional="hide" domain="[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id)]" context="{                                                     'append_fields': not parent.invoice_filter_type_domain and ['type_tax_use'],                                                     'active_test': True                                                }" options="{'no_create': True}" force_save="1" readonly="tax_line_id or (parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and account_type in ('asset_receivable', 'liability_payable'))"/>\n                                        <field name="debit" sum="Total Debit" invisible="display_type in ('line_section', 'line_subsection', 'line_note')" readonly="parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('product')"/>\n                                        <field name="credit" sum="Total Credit" invisible="display_type in ('line_section', 'line_subsection', 'line_note')" readonly="parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('product')"/>\n                                        <field name="balance" column_invisible="True"/>\n                                        <field name="discount_date" string="Discount Date" optional="hide"/>\n                                        <field name="discount_amount_currency" string="Discount Amount" optional="hide"/>\n\n                                        <field name="tax_tag_ids" widget="many2many_tags" string="Tax Grids" optional="show" options="{'no_create': True}" domain="[                                                     ('applicability', '=', 'taxes'),                                                     '|', ('country_id', '=', parent.tax_country_id),                                                     ('country_id', '=', False),                                                 ]"/>\n\n                                        <!-- Buttons -->\n                                        <button name="action_automatic_entry" type="object" icon="fa-calendar" string="Cut-Off" aria-label="Change Period" class="float-end" column_invisible="parent.move_type == 'entry' or parent.state != 'posted'" invisible="account_internal_group not in ('income', 'expense')" context="{'default_action': 'change_period'}"/>\n\n                                        <!-- Others fields -->\n                                        <field name="tax_line_id" column_invisible="True"/>\n                                        <field name="company_currency_id" column_invisible="True"/>\n                                        <field name="display_type" force_save="1" column_invisible="True"/>\n                                        <field name="company_id" column_invisible="True"/>\n                                        <field name="sequence" column_invisible="True"/>\n                                        <field name="id" column_invisible="True"/>\n                                        <field name="account_internal_group" column_invisible="True"/>\n                                        <field name="account_type" column_invisible="True"/>\n                                    