string=\\"Visa &amp; Work Permit\\">\\n                                        <label for=\\"visa_no\\"/>\\n                                        <div class=\\"o_wrap_label d-flex flex-row gap-3 align-items-baseline\\">\\n                                            <field name=\\"visa_no\\"/>\\n                                            <label for=\\"visa_expire\\" class=\\"flex-shrink-0\\" invisible=\\"not visa_no\\" string=\\"Expires on\\"/>\\n                                            <field name=\\"visa_expire\\" invisible=\\"not visa_no\\"/>\\n                                        </div>\\n                                        <label for=\\"permit_no\\"/>\\n                                        <div class=\\"o_wrap_label d-flex flex-row gap-3 align-items-baseline\\">\\n                                            <field name=\\"permit_no\\"/>\\n                                            <label for=\\"work_permit_expiration_date\\" class=\\"flex-shrink-0\\" invisible=\\"not permit_no\\" string=\\"Expires on\\"/>\\n                                            <field name=\\"work_permit_expiration_date\\" invisible=\\"not permit_no\\"/>\\n                                        </div>\\n                                        <field name=\\"work_permit_name\\" invisible=\\"1\\"/>\\n                                        <field name=\\"has_work_permit\\" widget=\\"work_permit_upload\\" filename=\\"work_permit_name\\" string=\\"Documento\\"/>\\n                                    </group>\\n                                    <group name=\\"citizenship\\" string=\\"Nacionalidad\\">\\n                                        <field name=\\"country_id\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\"/>\\n                                        <field name=\\"identification_id\\"/>\\n                                        <field name=\\"ssnid\\"/>\\n                                        <label for=\\"passport_id\\"/>\\n                                        <div class=\\"o_wrap_label d-flex flex-row gap-3 align-items-baseline\\">\\n                                            <field name=\\"passport_id\\"/>\\n                                            <label for=\\"passport_expiration_date\\" class=\\"flex-shrink-0\\" invisible=\\"not passport_id\\" string=\\"Expires on\\"/>\\n                                            <field name=\\"passport_expiration_date\\" invisible=\\"not passport_id\\"/>\\n                                        </div>\\n                                    </group>\\n                                    <group string=\\"Ubicación\\" name=\\"hr_location_group\\">\\n                                        <label for=\\"private_street\\" string=\\"Dirección privada\\"/>\\n                                        <div class=\\"o_address_format\\">\\n                                            <field name=\\"private_street\\" placeholder=\\"Calle...\\" class=\\"o_address_street\\"/>\\n                                            <field name=\\"private_street2\\" placeholder=\\"Calle 2...\\" class=\\"o_address_street\\"/>\\n                                            <field name=\\"private_city\\" placeholder=\\"Ciudad\\" class=\\"o_address_city\\"/>\\n                                            <field name=\\"private_state_id\\" class=\\"o_address_state\\" placeholder=\\"Provincia\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\" context=\\"{'default_country_id': private_country_id}\\" domain=\\"[('id', 'in', allowed_country_state_ids)]\\"/>\\n                                            <field name=\\"private_zip\\" placeholder=\\"C.P.\\" class=\\"o_address_zip\\"/>\\n                                            <field name=\\"private_country_id\\" placeholder=\\"País\\" class=\\"o_address_country\\" options=\\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\\"/>\\n                                        </div>\\n                                        <label for=\\"distance_home_work\\"/>\\n                                        <div class=\\"o_row\\" name=\\"div_km_home_work\\">\\n                                            <field name=\\"distance_home_work\\" class=\\"o_hr_narrow_field\\"/>\\n                                            <span><field name=\\"distance_home_work_unit\\"/></span>\\n                                        </div>\\n                                    </group>\\n                                    <group string=\\"Familia\\" name=\\"hr_family_group\\">\\n                                        <field name=\\"marital\\"/>\\n                                        <field name=\\"spouse_complete_name\\" invisible=\\"marital not in ['married', 'cohabitant']\\"/>\\n                                        <field name=\\"spouse_birthdate\\" invisible=\\"marital not in ['married', 'cohabitant']\\"/>\\n                                        <field name=\\"children\\"/>\\n                                    </group>\\n                                    <group string=\\"Educación\\" name=\\"hr_education_group\\">\\n                                        <field name=\\"certificate\\"/>\\n                                        <field name=\\"study_field\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page name=\\"payroll_information\\" string=\\"Nómina\\" groups=\\"hr.group_hr_manager\\">\\n                                <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n                                <group name=\\"payroll_group\\">\\n                                    <group name=\\"contract\\" groups=\\"hr.group_hr_user\\">\\n                                        <div colspan=\\"2\\" class=\\"col-lg-6 w-100 mt-4 mb-3 o_horizontal_separator text-uppercase fw-bolder small d-flex\\">\\n                                            <span>Contract Overview</span>\\n    