r_id\\" help=\\"Las horas laborables por defecto se establecen en la configuración.\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page name=\\"hr_settings\\" string=\\"Ajustes\\" groups=\\"hr.group_hr_user\\">\\n                                <group name=\\"settings_group\\">\\n                                    <group string=\\"Usuario\\" name=\\"user\\">\\n                                        <label for=\\"user_id\\"/>\\n                                        <div class=\\"o_row align-items-center\\">\\n                                            <field name=\\"user_id\\" string=\\"Usuario\\" placeholder=\\"Not linked to an user\\" domain=\\"[('company_ids', 'in', company_id), ('share', '=', False)]\\" context=\\"{                                                     'default_create_employee_id': id,                                                     'default_name': name,                                                     'default_phone': work_phone,                                                     'default_mobile': mobile_phone,                                                     'default_login': work_email,                                                     'default_partner_id': work_contact_id,                                                 }\\" widget=\\"many2one_avatar_user\\" groups=\\"base.group_erp_manager\\"/>\\n                                            <field name=\\"user_id\\" string=\\"Usuario\\" placeholder=\\"Not linked to an user\\" domain=\\"[('company_ids', 'in', company_id), ('share', '=', False)]\\" context=\\"{                                                     'default_create_employee_id': id,                                                     'default_name': name,                                                     'default_phone': work_phone,                                                     'default_mobile': mobile_phone,                                                     'default_login': work_email,                                                     'default_partner_id': work_contact_id,                                                 }\\" widget=\\"many2one_avatar_user\\" groups=\\"!base.group_erp_manager\\" options=\\"{'no_open': True}\\"/>\\n                                            <span invisible=\\"not user_id or is_user_active\\">\\n                                                (User is Inactive)\\n                                            </span>\\n                                            <field name=\\"tz\\" required=\\"id\\"/>\\n                                        </div>\\n                                    </group>\\n                                    <group name=\\"managers\\" string=\\"Aprobadores\\">\\n                                        <field name=\\"hr_responsible_id\\" widget=\\"many2one_avatar_user\\"/>\\n                                    </group>\\n                                    <group name=\\"application_group\\" string=\\"Ajustes de solicitud\\" invisible=\\"1\\"/>\\n                                    <group string=\\"Asistencia/Punto de Venta\\" name=\\"identification_group\\">\\n                                        <field name=\\"pin\\" string=\\"Código PIN\\"/>\\n                                        <label for=\\"barcode\\"/>\\n                                        <div class=\\"o_row\\">\\n                                            <field name=\\"barcode\\"/>\\n                                            <button string=\\"Generar\\" class=\\"btn btn-link\\" type=\\"object\\" name=\\"generate_random_barcode\\" invisible=\\"barcode\\"/>\\n                                            <button name=\\"204\\" string=\\"Imprimir credencial\\" class=\\"btn btn-link\\" type=\\"action\\" invisible=\\"not barcode\\"/>\\n                                        </div>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                    <chatter reload_on_follower=\\"True\\"/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Employee" js_class="hr_employee_form" duplicate="false">\n                    <header groups="hr.group_hr_user">\n                        <button string="Create User" name="action_create_user" type="object" class="btn btn-primary" invisible="user_id" groups="hr.group_hr_user" context="{'default_create_employee': True}"/>\n                        <button name="195" string="Launch Plan" type="action" groups="hr.group_hr_user" invisible="not active or not id" context="{'sort_by_responsible': True}"/>\n                        <field name="version_id" widget="versions_timeline" invisible="not id" options="{'clickable': True}" readonly="False"/>\n                    </header>\n                    <sheet>\n                        <div name="button_box" class="oe_button_box">\n                            <button name="action_open_versions" class="oe_stat_button" icon="fa-address-book" type="object" groups="hr.group_hr_user">\n                                <div class="o_stat_info">\n                                    History\n                                    <span class="o_stat_value">\n                                        <field name="versions_count"/>\n                                    </span>\n                                </div>\n                            </button>\n                        </div>\n                        <div class="d-flex flex-column flex-sm-row align-items-center">\n                            <div class="o_employee_avatar ms-2 p-0">\n                                <field name="image_1920" widget="image" class="m-0" options="{&quot;size&quot;: [128,158], &quot;zoom&quot;: true, &quot;preview_image&quot;:&quot;avatar_128&quot;}"/>\n                                <field name="show_hr_icon_display" invisible="1"/>\n                            </div>\n                            <div class="col px-4">\n                                <div class="oe_title ps-0 pe-sm-2">\n                                    <h1 class="d-flex flex-row align-items-center">\n                                        <field name="name" placeholder="Employee's Name" required="True" style="font-size: min(4vw, 2.6rem);"/>\n                                    </h1>\n                                    <h5 class="d-flex align-items-baseline mb-0">\n                                        <i class="fa fa-envelope fa-fw me-1 text-primary" title="Work Email"/>\n                                        <field name="work_email" widget="email" placeholder="e.g. johndoe@example.com" string="Work Email" class="w-100 w-sm-75"/>\n                                    </h5>\n                                    <h5 class="d-flex align-items-baseline mb-0">\n                                        <i class="fa fa-phone fa-fw me-1 text-primary" title="Work Phone"/>\n                                        <field name="work_phone" widget="phone" placeholder="Work Phone" string="Work Phone" class="w-100 w-sm-75"/>\n                                    </h5>\n                                    <h5 class="d-flex align-items-baseline mb-0">\n                                        <i class="fa fa-mobile fa-fw me-1 text-primary" title="Work Mobile"/>\n                                        <field name="mobile_phone" widget="phone" placeholder="Work Mobile" string="Work Mobile" class="w-100 w-sm-75"/>\n                                    </h5>\n                                    <h5>\n                                        <i class="fa fa-tags fa-fw me-1 text-primary" title="Tags"/>\n                                        <field name="category_ids" widget="many2many_tags" options="{'color_field': 'color', 'no_create_edit': True}" placeholder="e.g. Founder, Motorized, Building B, ..." groups="hr.group_hr_user"/>\n                                    </h5>\n                                </div>\n                            </div>\n                            <div class="align-self-start w-auto end-0 mt-2 d-flex align-items-center justify-content-end gap-2 o_presence_status_pill_wrapper">\n                                <div invisible="not user_id">\n                                    <widget name="hr_employee_chat" invisible="not context.get('chat_icon')"/>\n                                </div>\n                                <field name="hr_icon_display" invisible="not show_hr_icon_display or not id" widget="hr_presence_status"/>\n                            </div>\n                        </div>\n                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>\n                        <field name="employee_properties" columns="2"/>\n                        <notebook>\n                            <page name="work_information" string="Work">\n                                <div class="row" id="o_hr_work_information_container">\n                                    <div id="o_work_information" class="o_hr_column col-lg-7 d-flex flex-column">\n                                        <group string="work">\n                                            <field name="company_id" groups="base.group_multi_company" domain="[('id', 'in', allowed_company_ids)]"/>\n                                            <field name="department_id"/>\n                                            <field name="job_id" string="Job Position" context="{'default_no_of_recruitment': 0, 'default_is_favorite': False}" placeholder="e.g. Sales Manager"/>\n                                            <field name="job_title"/>\n                                            <field name="parent_id" widget="many2one_avatar_employee"/>\n                                        </group>\n                                        <group string="Location">\n                                            <field name="address_id" context="{'show_address': 1}" options="{&quot;highlight_first_line&quot;: True}"/>\n                                            <field name="work_location_id" context="{'default_address_id': address_id}" placeholder="e.g. Building 2, Remote, etc."/>\n                                        </group>\n                                        <group name="departure" string="Departure" invisible="active">\n                                            <field name="departure_reason_id" options="{'no_edit': True, 'no_create': True, 'no_open': True}"/>\n                                            <field name="departure_description"/>\n                                            <field name="departure_date"/>\n                                        </group>\n                                        <group string="Note" name="note" groups="hr.group_hr_user">\n                                            <field name="additional_note" placeholder="Provide additional information about this version..." colspan="2" nolabel="1"/>\n                                        </group>\n                                    </div>\n                                    <div id="o_employee_org_chart" class="o_hr_column col-lg-5"/>\n                                </div>\n                            </page>\n                            <page name="resume" string="Resume">\n                                <div class="row" id="o_hr_skills_resume_container">\n                                    <div id="o_employee_left" class="o_hr_skills_editable o_hr_skills_group o_hr_column o_group_resume col-lg-7 d-flex flex-column"/>\n                                    <div id="o_work_information_right" class="o_hr_skills_editable o_hr_skills_group o_hr_column o_group_skills col-lg-5"/>\n                                </div>\n                            </page>\n                            <page name="personal_information" string="Personal" groups="hr.group_hr_user">\n                                <group>\n                                    <group string="Private Contact">\n                                        <field name="private_email" placeholder="e.g. myprivateemail@example.com" string="Email"/>\n                                        <field name="private_phone" widget="phone" string="Phone"/>\n                                        <field name="has_multiple_bank_accounts" invisible="1"/>\n                                        <field name="is_trusted_bank_account" invisible="1"/>\n                                        <field name="bank_account_ids" invisible="1" widget="many2many_tags" options="{'color_field': 'color'}"/>\n                                        <label for="bank_account_ids"/>\n                                        <div class="d-flex align-items-start justify-content-between" invisible="not has_multiple_bank_accounts">\n                                                <field name="bank_account_ids" widget="many2many_tags_salary_bank" context="{'default_partner_id': work_contact_id}" options="{'color_field': 'color', 'no_quick_create': True, 'edit_tags': True}" readonly="not id"/>\n                                            <div class="pt-0 ms-2">\n                                                <button name="action_open_allocation_wizard" type="object" string="Salary Allocation" class="btn btn-link p-0 ms-auto text-nowrap"/>\n                                            </div>\n                                        </div>\n\n                                        <div class="o-row d-flex justify-content-between gap-2 align-items-start" invisible="has_multiple_bank_accounts">\n                                            <field name="bank_account_ids" widget="many2many_tags_salary_bank" context="{'default_partner_id': work_contact_id}" options="{'color_field': 'color', 'no_quick_create': True, 'edit_tags': True}" readonly="not id"/>\n                                            <div class="d-flex align-items-start" invisible="not bank_account_ids">\n                                                <span class="d-flex w-50">\n                                                    <span invisible="is_trusted_bank_account" class="text-muted">Untrusted</span>\n                                                    <span invisible="not is_trusted_bank_account" class="text-success">Trusted</span>\n                                                </span>\n                                                <button title="Trust Bank Account" class="pt-0" icon="fa-toggle-off fa-lg" type="object" name="action_toggle_primary_bank_account_trust" invisible="is_trusted_bank_account"/>\n                                                <button title="Untrust Bank Account" class="button-on pt-0" icon="fa-toggle-on fa-lg" type="object" name="action_toggle_primary_bank_account_trust" invisible="not is_trusted_bank_account"/>\n                                            </div>\n                                        </div>\n                                    </group>\n                                    <group string="Personal Information" name="hr_birth_group">\n                                        <field name="legal_name"/>\n                                        <label for="birthday"/>\n                                        <div class="o_row" name="div_km_home_work">\n                                            <field name="birthday" class="o_hr_narrow_field"/>\n                                            <span invisible="not birthday">\n                                                <label for="birthday_public_display" class="fw-bold text-900 form-check-label ms-3"/>\n                                                <field name="birthday_public_display" class="ms-3"/>\n                                            </span>\n                                        </div>\n                                        <label for="place_of_birth"/>\n                                        <div class="o_row" name="birth_location">\n                                            <field name="place_of_birth" class="oe_inline o_hr_narrow_field" nolabel="1" placeholder="City"/>\n                                            <div class="mx-3 flex-grow-0">─</div>\n                                            <field name="country_of_birth" class="oe_inline o_hr_narrow_field" nolabel="1" placeholder="Country"/>\n                                        </div>\n                                        <field name="sex" string="Gender"/>\n                                    </group>\n                                    <group string="Emergency Contact">\n                                        <field name="emergency_contact" string="Contact"/>\n                                        <field name="emergency_phone" class="o_force_ltr" string="Phone"/>\n                                    </group>\n                                    <group string="Visa &amp; Work Permit">\n                                        <label for="visa_no"/>\n                                        <div class="o_wrap_label d-flex flex-row gap-3 align-items-baseline">\n                                            <field name="visa_no"/>\n                                            <label for="visa_expire" class="flex-shrink-0" invisible="not visa_no" string="Expires on"/>\n                                            <field name="visa_expire" invisible="not visa_no"/>\n                                        </div>\n                                        <label for="permit_no"/>\n                                        <div class="o_wrap_label d-flex flex-row gap-3 align-items-baseline">\n                                            <field name="permit_no"/>\n                                            <label for="work_permit_expiration_date" class="flex-shrink-0" invisible="not permit_no" string="Expires on"/>\n                                           