 t-att-class="is_product_tmpl and 'fw-bold px-1' or None">\n                                        <a t-if="is_html_type" href="#" class="o_action" t-att-data-model="is_product_tmpl and 'product.template' or 'product.product'" t-att-data-res-id="product['id']">\n                                            <span t-out="product['name']">Virtual Interior Design</span>\n                                        </a>\n                                        <span t-else="" t-out="product['name']">Acme Widget</span>\n                                    </td>\n                                    <td groups="uom.group_uom" class="px-1" t-out="product['uom']"/>\n                                    <t t-foreach="quantities" t-as="qty">\n                                        <td class="text-end px-1">\n                                            <span t-out="product['price'][qty]" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: pricelist.currency_id}">$15.00</span>\n                                        </td>\n                                    </t>\n                                </tr>\n                                <t t-if="is_product_tmpl and 'variants' in product">\n                                    <tr t-foreach="product['variants']" t-as="variant">\n                                        <td class="px-1">\n                                            <a t-if="is_html_type" href="#" class="o_action ms-4" data-model="product.product" t-att-data-res-id="variant['id']">\n                                                <span t-out="variant['name']">Acme Widget - Blue</span>\n                                            </a>\n                                            <span t-else="" class="ms-4" t-out="variant['name']">Acme Widget - Blue</span>\n                                        </td>\n                                        <td groups="uom.group_uom" class="px-1" t-out="product['uom']"/>\n                                        <t t-foreach="quantities" t-as="qty">\n                                            <td class="text-end px-1">\n                                                <span t-out="variant['price'][qty]" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: pricelist.currency_id}">$14.00</span>\n                                            </td>\n                                        </t>\n                                    </tr>\n                                </t>\n                            </t>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n            <div class="oe_structure"/>\n        </div>\n    </t>\n\n    	f	t	2025-11-28 09:05:14.534767	2025-11-28 09:05:14.534767	f
815	16	\N	1	1	Payment Express Checkout	\N	payment.express_checkout	qweb	payment/views/express_checkout_templates.xml	primary	{"en_US": "<t name=\\"Payment Express Checkout\\" t-name=\\"payment.express_checkout\\">\\n        <!-- Parameters description:\\n            - reference_prefix: The custom prefix to compute the full transaction reference.\\n            - amount: The amount to pay.\\n            - minor_amount: The amount to pay in the minor units of its currency.\\n            - currency: The currency of the payment, as a `res.currency` record.\\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\\n            - merchant_name: The merchant name.\\n            - payment_method_unknown_id: The ID of the \\"Unknown\\" payment method record, to use as\\n                                         the generic express checkout method.\\n            - payment_access_token: The access token used to authenticate the partner. Since this\\n                                    template is loaded in the shopping cart, this parameter is\\n                                    called `payment_access_token` to prevent mixing up with the\\n                                    `access_token` used for abandoned carts.\\n            - shipping_info_required: Whether the shipping information is required or not.\\n            - transaction_route: The route used to create a transaction when the user clicks Pay.\\n            - shipping_address_update_route: The route where available carriers are computed based\\n                                             on the (partial) shipping information available.\\n                                             Optional.\\n            - express_checkout_route: The route where the billing and shipping information are sent.\\n            - landing_route: The route the user is redirected to after the transaction.\\n            - payment_access_token: The access token used to authenticate the partner. Since this\\n                                    template is loaded in the shopping cart, this parameter is\\n                                    called `payment_access_token` to prevent mixing up with the\\n                                    `access_token` used for abandoned carts.\\n        -->\\n        <form name=\\"o_payment_express_checkout_form\\" class=\\"container\\" t-att-data-reference-prefix=\\"reference_prefix\\" t-att-data-amount=\\"amount\\" t-att-data-minor-amount=\\"minor_amount\\" t-att-data-currency-id=\\"currency and currency.id\\" t-att-data-currency-name=\\"currency.name.lower()\\" t-att-data-merchant-name=\\"merchant_name\\" t-att-data-partner-id=\\"partner_id\\" t-att-data-payment-method-unknown-id=\\"payment_method_unknown_id\\" t-att-data-access-token=\\"payment_access_token\\" t-att-data-shipping-info-required=\\"shipping_info_required\\" t-att-data-delivery-amount=\\"delivery_amount\\" t-att-data-transaction-route=\\"transaction_route\\" t-att-data-shipping-address-update-route=\\"shipping_address_update_route\\" t-att-data-express-checkout-route=\\"express_checkout_route\\" t-att-data-landing-route=\\"landing_route\\">\\n            <t t-set=\\"provider_sudo\\" t-value=\\"providers_sudo[:1]\\"/>\\n            <t t-set=\\"express_checkout_form_xml_id\\" t-value=\\"provider_sudo.express_checkout_form_view_id.xml_id\\"/>\\n            <t t-if=\\"express_checkout_form_xml_id\\">\\n                <t t-call=\\"{{express_checkout_form_xml_id}}\\"/>\\n            </t>\\n        </form>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Payment Express Checkout" t-name="payment.express_checkout">\n        <!-- Parameters description:\n            - reference_prefix: The custom prefix to compute the full transaction reference.\n            - amount: The amount to pay.\n            - minor_amount: The amount to pay in the minor units of its currency.\n            - currency: The currency of the payment, as a `res.currency` record.\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\n            - merchant_name: The merchant name.\n            - payment_method_unknown_id: The ID of the "Unknown" payment method record, to use as\n                                         the generic express checkout method.\n            - payment_access_token: The access token used to authenticate the partner. Since this\n                                    template is loaded in the shopping cart, this parameter is\n                                    called `payment_access_token` to prevent mixing up with the\n                                    `access_token` used for abandoned carts.\n            - shipping_info_required: Whether the shipping information is required or not.\n            - transaction_route: The route used to create a transaction when the user clicks Pay.\n            - shipping_address_update_route: The route where available carriers are computed based\n                                             on the (partial) shipping information available.\n                                             Optional.\n            - express_checkout_route: The route where the billing and shipping information are sent.\n            - landing_route: The route the user is redirected to after the transaction.\n            - payment_access_token: The access token used to authenticate the partner. Since this\n                                    template is loaded in the shopping cart, this parameter is\n                                    called `payment_access_token` to prevent mixing up with the\n                                    `access_token` used for abandoned carts.\n        -->\n        <form name="o_payment_express_checkout_form" class="container" t-att-data-reference-prefix="reference_prefix" t-att-data-amount="amount" t-att-data-minor-amount="minor_amount" t-att-data-currency-id="currency and currency.id" t-att-data-currency-name="currency.name.lower()" t-att-data-merchant-name="merchant_name" t-att-data-partner-id="partner_id" t-att-data-payment-method-unknown-id="payment_method_unknown_id" t-att-data-access-token="payment_access_token" t-att-data-shipping-info-required="shipping_info_required" t-att-data-delivery-amount="delivery_amount" t-att-data-transaction-route="transaction_route" t-att-data-shipping-address-update-route="shipping_address_update_route" t-att-data-express-checkout-route="express_checkout_route" t-att-data-landing-route="landing_route">\n            <t t-set="provider_sudo" t-value="providers_sudo[:1]"/>\n            <t t-set="express_checkout_form_xml_id" t-value="provider_sudo.express_checkout_form_view_id.xml_id"/>\n            <t t-if="express_checkout_form_xml_id">\n                <t t-call="{{express_checkout_form_xml_id}}"/>\n            </t>\n        </form>\n    </t>\n\n	f	t	2025-11-28 09:05:16.026603	2025-11-28 09:05:16.026603	f
816	16	\N	1	1	Payment Form	\N	payment.form	qweb	payment/views/payment_form_templates.xml	primary	{"en_US": "<t name=\\"Payment Form\\" t-name=\\"payment.form\\">\\n        <!-- Form customization parameters:\\n            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.\\n            - allow_token_selection: Whether tokens can be selected for payment or assignation\\n                                     (through the `assign_token_route` parameter); default: `True`.\\n            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.\\n            - default_token_id: The id of the token that should be pre-selected; default: `None`.\\n            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is\\n                                           shown; used only in `payment` mode.\\n            - display_submit_button: Whether the submit button is displayed; default: `True`.\\n            - submit_button_label: The label of the submit button; default: 'Pay'/'Save'.\\n        -->\\n        <!-- Payment context:\\n            - reference_prefix: The custom prefix to compute the full transaction reference.\\n            - amount: The amount to pay.\\n            - currency: The currency of the payment, as a `res.currency` record.\\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\\n                                    recordset.\\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\\n            - transaction_route: The route to call to create the transaction.\\n            - assign_token_route: The route to call to assign a new or existing token to a record.\\n            - landing_route: The route the user is redirected to after payment.\\n            - access_token: The access token used to authenticate the partner.\\n        -->\\n        <t t-set=\\"mode\\" t-value=\\"mode or 'payment'\\"/>\\n        <t t-set=\\"allow_token_selection\\" t-value=\\"True if allow_token_selection is None else allow_token_selection\\"/>\\n        <t t-set=\\"allow_token_deletion\\" t-value=\\"allow_token_deletion or False\\"/>\\n        <t t-set=\\"selected_token_id\\" t-value=\\"allow_token_selection and (default_token_id or tokens_sudo[:1].id)\\"/>\\n        <t t-set=\\"selected_method_id\\" t-value=\\"not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id\\"/>\\n        <t t-set=\\"collapse_payment_methods\\" t-value=\\"tokens_sudo and allow_token_selection and payment_methods_sudo\\"/>\\n        <t t-set=\\"display_submit_button\\" t-value=\\"True if display_submit_button is None else display_submit_button\\"/>\\n        <t t-set=\\"pay_label\\">Pay</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"save_label\\">Save</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"submit_button_label\\" t-value=\\"submit_button_label or (pay_label if mode == 'payment' else save_label)\\"/>\\n        <form t-if=\\"payment_methods_sudo or tokens_sudo\\" id=\\"o_payment_form\\" class=\\"o_payment_form\\" t-att-data-mode=\\"mode\\" t-att-data-reference-prefix=\\"reference_prefix\\" t-att-data-amount=\\"amount\\" t-att-data-currency-id=\\"currency and currency.id\\" t-att-data-partner-id=\\"partner_id\\" t-att-data-transaction-route=\\"transaction_route\\" t-att-data-assign-token-route=\\"assign_token_route\\" t-att-data-landing-route=\\"landing_route\\" t-att-data-access-token=\\"access_token\\">\\n            <div id=\\"o_payment_form_options\\" class=\\"d-flex flex-column gap-3\\">\\n                <!-- === Payment tokens === -->\\n                <div t-if=\\"tokens_sudo\\">\\n                    <!-- === Header === -->\\n                    <h4 id=\\"o_payment_tokens_heading\\">\\n                        Your payment methods\\n                    </h4>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"tokens_sudo\\" t-as=\\"token_sudo\\">\\n                            <li name=\\"o_payment_option\\" t-att-class=\\"'list-group-item d-flex flex-column gap-2 py-3'                                              + (' o_outline' if allow_token_selection else '')\\">\\n                                <t t-call=\\"payment.token_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"token_sudo.id == selected_token_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n                <!-- === Payment methods === -->\\n                <div t-if=\\"payment_methods_sudo\\" id=\\"o_payment_methods\\" t-att-class=\\"'collapse' if collapse_payment_methods else ''\\">\\n                    <!-- === Header === -->\\n                    <p t-attf-class=\\"mb-3 {{collapse_payment_methods and 'h5' or 'h4'}}\\">\\n                        <t t-if=\\"not collapse_payment_methods\\">Payment method</t>\\n                        <t t-else=\\"\\">Other payment methods</t>\\n                        <t t-call=\\"payment.availability_report_button\\"/>\\n                    </p>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"payment_methods_sudo\\" t-as=\\"pm_sudo\\">\\n                            <li name=\\"o_payment_option\\" class=\\"list-group-item d-flex flex-column gap-2 py-3 o_outline\\">\\n                                <t t-call=\\"payment.method_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"pm_sudo.id == selected_method_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n            </div>\\n            <div class=\\"d-flex justify-content-end flex-column flex-md-row gap-2 my-2\\">\\n                <!-- === Expand payment methods button === -->\\n                <button t-if=\\"collapse_payment_methods\\" name=\\"o_payment_expand_button\\" type=\\"button\\" href=\\"#o_payment_methods\\" class=\\"btn btn-link\\" data-bs-toggle=\\"collapse\\">\\n                    Choose another method <i class=\\"oi oi-arrow-down\\"/>\\n                </button>\\n                <!-- === Submit button === -->\\n                <t t-if=\\"display_submit_button\\" t-call=\\"payment.submit_button\\"/>\\n            </div>\\n            <!-- === Availability report === -->\\n            <t t-call=\\"payment.availability_report\\"/>\\n        </form>\\n        <t t-else=\\"\\" t-call=\\"payment.no_pms_available_warning\\"/>\\n    </t>", "es_ES": "<t name=\\"Payment Form\\" t-name=\\"payment.form\\">\\n        <!-- Form customization parameters:\\n            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.\\n            - allow_token_selection: Whether tokens can be selected for payment or assignation\\n                                     (through the `assign_token_route` parameter); default: `True`.\\n            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.\\n            - default_token_id: The id of the token that should be pre-selected; default: `None`.\\n            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is\\n                                           shown; used only in `payment` mode.\\n            - display_submit_button: Whether the submit button is displayed; default: `True`.\\n            - submit_button_label: The label of the submit button; default: 'Pay'/'Save'.\\n        -->\\n        <!-- Payment context:\\n            - reference_prefix: The custom prefix to compute the full transaction reference.\\n            - amount: The amount to pay.\\n            - currency: The currency of the payment, as a `res.currency` record.\\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\\n                                    recordset.\\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\\n            - transaction_route: The route to call to create the transaction.\\n            - assign_token_route: The route to call to assign a new or existing token to a record.\\n            - landing_route: The route the user is redirected to after payment.\\n            - access_token: The access token used to authenticate the partner.\\n        -->\\n        <t t-set=\\"mode\\" t-value=\\"mode or 'payment'\\"/>\\n        <t t-set=\\"allow_token_selection\\" t-value=\\"True if allow_token_selection is None else allow_token_selection\\"/>\\n        <t t-set=\\"allow_token_deletion\\" t-value=\\"allow_token_deletion or False\\"/>\\n        <t t-set=\\"selected_token_id\\" t-value=\\"allow_token_selection and (default_token_id or tokens_sudo[:1].id)\\"/>\\n        <t t-set=\\"selected_method_id\\" t-value=\\"not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id\\"/>\\n        <t t-set=\\"collapse_payment_methods\\" t-value=\\"tokens_sudo and allow_token_selection and payment_methods_sudo\\"/>\\n        <t t-set=\\"display_submit_button\\" t-value=\\"True if display_submit_button is None else display_submit_button\\"/>\\n        <t t-set=\\"pay_label\\">Pagar</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"save_label\\">Guardar</t> <!-- Allow translating the label. -->\\n        <t t-set=\\"submit_button_label\\" t-value=\\"submit_button_label or (pay_label if mode == 'payment' else save_label)\\"/>\\n        <form t-if=\\"payment_methods_sudo or tokens_sudo\\" id=\\"o_payment_form\\" class=\\"o_payment_form\\" t-att-data-mode=\\"mode\\" t-att-data-reference-prefix=\\"reference_prefix\\" t-att-data-amount=\\"amount\\" t-att-data-currency-id=\\"currency and currency.id\\" t-att-data-partner-id=\\"partner_id\\" t-att-data-transaction-route=\\"transaction_route\\" t-att-data-assign-token-route=\\"assign_token_route\\" t-att-data-landing-route=\\"landing_route\\" t-att-data-access-token=\\"access_token\\">\\n            <div id=\\"o_payment_form_options\\" class=\\"d-flex flex-column gap-3\\">\\n                <!-- === Payment tokens === -->\\n                <div t-if=\\"tokens_sudo\\">\\n                    <!-- === Header === -->\\n                    <h4 id=\\"o_payment_tokens_heading\\">\\n                        Sus métodos de pago\\n                    </h4>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"tokens_sudo\\" t-as=\\"token_sudo\\">\\n                            <li name=\\"o_payment_option\\" t-att-class=\\"'list-group-item d-flex flex-column gap-2 py-3'                                              + (' o_outline' if allow_token_selection else '')\\">\\n                                <t t-call=\\"payment.token_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"token_sudo.id == selected_token_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n                <!-- === Payment methods === -->\\n                <div t-if=\\"payment_methods_sudo\\" id=\\"o_payment_methods\\" t-att-class=\\"'collapse' if collapse_payment_methods else ''\\">\\n                    <!-- === Header === -->\\n                    <p t-attf-class=\\"mb-3 {{collapse_payment_methods and 'h5' or 'h4'}}\\">\\n                        <t t-if=\\"not collapse_payment_methods\\">Método de pago</t>\\n                        <t t-else=\\"\\">Otros métodos de pago</t>\\n                        <t t-call=\\"payment.availability_report_button\\"/>\\n                    </p>\\n                    <!-- === Body === -->\\n                    <ul class=\\"list-group\\">\\n                        <t t-foreach=\\"payment_methods_sudo\\" t-as=\\"pm_sudo\\">\\n                            <li name=\\"o_payment_option\\" class=\\"list-group-item d-flex flex-column gap-2 py-3 o_outline\\">\\n                                <t t-call=\\"payment.method_form\\">\\n                                    <t t-set=\\"is_selected\\" t-value=\\"pm_sudo.id == selected_method_id\\"/>\\n                                </t>\\n                            </li>\\n                        </t>\\n                    </ul>\\n                </div>\\n            </div>\\n            <div class=\\"d-flex justify-content-end flex-column flex-md-row gap-2 my-2\\">\\n                <!-- === Expand payment methods button === -->\\n                <button t-if=\\"collapse_payment_methods\\" name=\\"o_payment_expand_button\\" type=\\"button\\" href=\\"#o_payment_methods\\" class=\\"btn btn-link\\" data-bs-toggle=\\"collapse\\">\\n                    Elija otro método <i class=\\"oi oi-arrow-down\\"/>\\n                </button>\\n                <!-- === Submit button === -->\\n                <t t-if=\\"display_submit_button\\" t-call=\\"payment.submit_button\\"/>\\n            </div>\\n            <!-- === Availability report === -->\\n            <t t-call=\\"payment.availability_report\\"/>\\n        </form>\\n        <t t-else=\\"\\" t-call=\\"payment.no_pms_available_warning\\"/>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Payment Form" t-name="payment.form">\n        <!-- Form customization parameters:\n            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.\n            - allow_token_selection: Whether tokens can be selected for payment or assignation\n                                     (through the `assign_token_route` parameter); default: `True`.\n            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.\n            - default_token_id: The id of the token that should be pre-selected; default: `None`.\n            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is\n                                           shown; used only in `payment` mode.\n            - display_submit_button: Whether the submit button is displayed; default: `True`.\n            - submit_button_label: The label of the submit button; default: 'Pay'/'Save'.\n        -->\n        <!-- Payment context:\n            - reference_prefix: The custom prefix to compute the full transaction reference.\n            - amount: The amount to pay.\n            - currency: The currency of the payment, as a `res.currency` record.\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\n                                    recordset.\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\n            - transaction_route: The route to call to create the transaction.\n            - assign_token_route: The route to call to assign a new or existing token to a record.\n            - landing_route: The route the user is redirected to after payment.\n            - access_token: The access token used to authenticate the partner.\n        -->\n        <t t-set="mode" t-value="mode or 'payment'"/>\n        <t t-set="allow_token_selection" t-value="True if allow_token_selection is None else allow_token_selection"/>\n        <t t-set="allow_token_deletion" t-value="allow_token_deletion or False"/>\n        <t t-set="selected_token_id" t-value="allow_token_selection and (default_token_id or tokens_sudo[:1].id)"/>\n        <t t-set="selected_method_id" t-value="not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id"/>\n        <t t-set="collapse_payment_methods" t-value="tokens_sudo and allow_token_selection and payment_methods_sudo"/>\n        <t t-set="display_submit_button" t-value="True if display_submit_button is None else display_submit_button"/>\n        <t t-set="pay_label">Pay</t> <!-- Allow translating the label. -->\n        <t t-set="save_label">Save</t> <!-- Allow translating the label. -->\n        <t t-set="submit_button_label" t-value="submit_button_label or (pay_label if mode == 'payment' else save_label)"/>\n        <form t-if="payment_methods_sudo or tokens_sudo" id="o_payment_form" class="o_payment_form" t-att-data-mode="mode" t-att-data-reference-prefix="reference_prefix" t-att-data-amount="amount" t-att-data-currency-id="currency and currency.id" t-att-data-partner-id="partner_id" t-att-data-transaction-route="transaction_route" t-att-data-assign-token-route="assign_token_route" t-att-data-landing-route="landing_route" t-att-data-access-token="access_token">\n            <div id="o_payment_form_options" class="d-flex flex-column gap-3">\n                <!-- === Payment tokens === -->\n                <div t-if="tokens_sudo">\n                    <!-- === Header === -->\n                    <h4 id="o_payment_tokens_heading">\n                        Your payment methods\n                    </h4>\n                    <!-- === Body === -->\n                    <ul class="list-group">\n                        <t t-foreach="tokens_sudo" t-as="token_sudo">\n                            <li name="o_payment_option" t-att-class="'list-group-item d-flex flex-column gap-2 py-3'                                              + (' o_outline' if allow_token_selection else '')">\n                                <t t-call="payment.token_form">\n                                    <t t-set="is_selected" t-value="token_sudo.id == selected_token_id"/>\n                                </t>\n                            </li>\n                        </t>\n                    </ul>\n                </div>\n                <!-- === Payment methods === -->\n                <div t-if="payment_methods_sudo" id="o_payment_methods" t-att-class="'collapse' if collapse_payment_methods else ''">\n                    <!-- === Header === -->\n                    <p t-attf-class="mb-3 {{collapse_payment_methods and 'h5' or 'h4'}}">\n                        <t t-if="not collapse_payment_methods">Payment method</t>\n                        <t t-else="">Other payment methods</t>\n                        <t t-call="payment.availability_report_button"/>\n                    </p>\n                    <!-- === Body === -->\n                    <ul class="list-group">\n                        <t t-foreach="payment_methods_sudo" t-as="pm_sudo">\n                            <li name="o_payment_option" class="list-group-item d-flex flex-column gap-2 py-3 o_outline">\n                                <t t-call="payment.method_form">\n                                    <t t-set="is_selected" t-value="pm_sudo.id == selected_method_id"/>\n                                </t>\n                            </li>\n                        </t>\n                    </ul>\n                </div>\n            </div>\n            <div class="d-flex justify-content-end flex-column flex-md-row gap-2 my-2">\n                <!-- === Expand payment methods button === -->\n                <button t-if="collapse_payment_methods" name="o_payment_expand_button" type="button" href="#o_payment_methods" class="btn btn-link" data-bs-toggle="collapse">\n                    Choose another method <i class="oi oi-arrow-down"/>\n                </button>\n                <!-- === Submit button === -->\n                <t t-if="display_submit_button" t-call="payment.submit_button"/>\n            </div>\n            <!-- === Availability report === -->\n            <t t-call="payment.availability_report"/>\n        </form>\n        <t t-else="" t-call="payment.no_pms_available_warning"/>\n    </t>\n\n    	f	t	2025-11-28 09:05:16.026603	2025-11-28 09:05:16.026603	f
