ayment details) === -->\\n                <div class=\\"col\\">\\n                    <p t-out=\\"token_sudo.display_name\\" t-att-class=\\"'mb-0 small fw-bold text-break'                                     + (' ms-4 ms-md-0' if allow_token_selection else '')\\"/>\\n                </div>\\n                <!-- === Provider name (only for desktop and tablet) === -->\\n                <t t-set=\\"hide_secured_by\\" t-value=\\"False\\"/>\\n                <div class=\\"col d-none d-md-block\\">\\n                    <p name=\\"o_payment_secured_by_desktop\\" t-att-class=\\"'mb-0 small text-600'                                     + (' ms-4 ms-md-0' if allow_token_selection else '')                                     + (' d-none' if hide_secured_by else '')\\">\\n                        <span><i class=\\"fa fa-lock\\"/> Secured by</span>\\n                        <span t-out=\\"dict(provider_sudo._fields['code']._description_selection(                                          provider_sudo.env                                      ))[provider_sudo.code]\\" class=\\"text-break\\"/>\\n                    </p>\\n                </div>\\n            </div>\\n            <!-- === Payment method logo === -->\\n            <div>\\n                <t t-call=\\"payment.form_logo\\" logo_pm_sudo=\\"token_sudo.payment_method_id\\"/>\\n            </div>\\n        </div>\\n        <!-- === Inline form === -->\\n        <div t-if=\\"inline_form_xml_id\\" name=\\"o_payment_inline_form\\" class=\\"position-relative d-none\\">\\n            <t t-call=\\"{{inline_form_xml_id}}\\"/>\\n        </div>\\n        <!-- === Provider name (only for mobile) === -->\\n        <p name=\\"o_payment_secured_by_mobile\\" t-att-class=\\"'align-self-center d-block d-md-none mb-0 small text-600'                         + (' d-none' if hide_secured_by else '')\\">\\n            <span><i class=\\"fa fa-lock\\"/> Secured by</span>\\n            <span t-out=\\"dict(provider_sudo._fields['code']._descripti