.\n            - is_selected: Whether the radio button of the payment method should be checked.\n        -->\n        <t t-set="provider_sudo" t-value="pm_sudo.provider_ids.filtered(lambda p: p in providers_sudo)[:1]"/>\n        <t t-set="is_test" t-value="provider_sudo.state == 'test'"/>\n        <t t-set="is_unpublished" t-value="not provider_sudo.is_published"/>\n        <t t-set="pms_to_display_sudo" t-value="pm_sudo.brand_ids or pm_sudo"/>\n        <t t-set="inline_form_xml_id" t-value="provider_sudo.inline_form_view_id.xml_id"/>\n        <div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-0 p-0" for="o_payment_radio">\n            <div class="form-check d-flex flex-grow-1 flex-wrap mb-0">\n                <div class="d-flex justify-content-between align-items-center gap-2 flex-wrap w-100">\n                    <!-- === Radio button === -->\n                    <input t-attf-id="o_payment_method_{{pm_sudo.id}}" name="o_payment_radio" type="radio" t-att-checked="is_selected" class="form-check-input position-absolute mt-0" data-payment-option-type="payment_method" t-att-data-payment-option-id="pm_sudo.id" t-att-data-payment-method-code="pm_sudo.code" t-att-data-provider-id="provider_sudo.id" t-att-data-provider-code="provider_sudo._get_code()" t-att-data-provider-state="provider_sudo.state"/>\n                    <div class="d-flex gap-2 flex-grow-1 me-auto">\n                        <!-- === Method label === -->\n                        <label t-out="pm_sudo.name" class="o_payment_option_label mb-0 text-break" t-attf-for="o_payment_method_{{pm_sudo.id}}"/>\n                        <div class="d-flex flex-nowrap gap-2 mt-1">\n                            <!-- === "Unpublished" icon === -->\n                            <t t-if="is_unpublished" t-call="payment.form_icon">\n                                <t t-set="icon_name" t-value="'eye-slash'"/>\n                                <t t-set="color_name" t-value="'danger'"/>\n                                <t t-set="title">Unpublished</t>\n                            </t>\n                            <!-- === "Test mode" icon === -->\n                            <t t-if="is_test" t-call="payment.form_icon">\n                                <t t-set="icon_name" t-value="'exclamation-triangle'"/>\n                                <t t-set="color_name" t-value="'warning'"/>\n                                <t t-set="title">Test mode</t>\n                            </t>\n                        </div>\n                    </div>\n                    <div class="gap-1 flex-wrap d-flex">\n                        <!-- === Payment method logos === -->\n                        <t t-set="pm_index" t-value="0"/>\n                        <t t-foreach="pms_to_display_sudo" t-as="pm_to_display_sudo">\n                            <t t-if="pm_index &lt; 4" t-call="payment.form_logo">\n                                <t t-set="logo_pm_sudo" t-value="pm_to_display_sudo"/>\n                            </t>\n                            <t t-set="pm_index" t-value="pm_index + 1"/>\n                        </t>\n                    </div>\n                </div>\n            </div>\n            <!-- === Help message === -->\n            <div t-if="not is_html_empty(provider_sudo.pre_msg)" class="w-100 mb-0 ms-4 small text-600">\n                <t t-out="provider_sudo.pre_msg"/>\n            </div>\n        </div>\n        <!-- === Inline form === -->\n        <div name="o_payment_inline_form" class="position-relative d-none">\n            <t t-if="inline_form_xml_id and provider_sudo._should_build_inline_form(                          is_validation=mode == 'validation'                      )" t-call="{{inline_form_xml_id}}">\n                <t t-set="provider_id" t-value="provider_sudo.id"/>\n            </t>\n            <div class="d-flex flex-column flex-sm-row align-md-items-center justify-content-between                         gap-3 mt-2">\n                <!-- === Tokenization checkbox === -->\n                <div t-if="mode == 'payment'                            and pm_sudo.support_tokenization                            and show_tokenize_input_mapping[provider_sudo.id]" name="o_payment_tokenize_container" class="o-checkbox form-check m-0">\n                    <label>\n                        <input name="o_payment_tokenize_checkbox" type="checkbox" class="form-check-input"/>\n                        <small class="text-600">Save my payment details</small>\n                    </label>\n                </div>\n                <!-- === Provider name === -->\n                <t t-set="hide_secured_by" t-value="False"/>\n                <p name="o_payment_secured_by" t-att-class="'align-self-end mb-0 mx-auto me-sm-0 small text-600'                                 + (' d-none' if hide_secured_by else '')">\n                    <span><i class="fa fa-lock"/> Secured by</span>\n                    <span t-out="dict(provider_sudo._fields['code']._description_selection(                                      provider_sudo.env                                  ))[provider_sudo.code]" class="text-break"/>\n                </p>\n            </div>\n        </div>\n    </t>\n\n    	f	t	2025-11-28 09:05:16.026603	2025-11-28 09:05:16.026603	f
