e_deadline &lt; current_date and state not in ['1_done', '1_canceled']\\" optional=\\"show\\"/>\\n                                    <field name=\\"priority\\" widget=\\"priority\\" optional=\\"show\\" nolabel=\\"1\\" width=\\"20px\\" readonly=\\"1\\"/>\\n                                    <field name=\\"tag_ids\\" widget=\\"many2many_tags\\" options=\\"{'color_field': 'color'}\\" optional=\\"hide\\"/>\\n                                    <field name=\\"stage_id\\" optional=\\"show\\"/>\\n                                    <button name=\\"action_open_task\\" type=\\"object\\" title=\\"View Task\\" string=\\"View Task\\" class=\\"btn btn-link float-end\\" context=\\"{'form_view_ref': 'project.project_sharing_project_task_view_form'}\\" invisible=\\"project_id != context.get('active_id')\\"/>\\n                                </list>\\n                            </field>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <!-- field used inside the chatter to know if the portal user is follower or not -->\\n                <field name=\\"message_is_follower\\" invisible=\\"1\\"/>\\n                <field name=\\"display_follow_button\\" invisible=\\"1\\"/>\\n                <chatter/>\\n            </form>", "es_ES": "<form string=\\"Compartir proyectos: tarea\\" class=\\"o_form_project_tasks\\">\\n                <header>\\n                    <field name=\\"stage_id\\" widget=\\"statusbar_duration\\" options=\\"{'clickable': '1', 'fold_field': 'fold'}\\" invisible=\\"not project_id and not stage_id\\"/>\\n                </header>\\n                <div groups=\\"base.group_user\\" role=\\"status\\" class=\\"alert alert-info alert-dismissible rounded-0 fade show d-print-none css_editable_mode_hidden\\">\\n                    <div class=\\"text-center\\">Esta es una vista previa de cómo se verá el proyecto cuando se comparta con los clientes y tengan acceso de edición.\\n                        <a name