 name=\\"qr_code\\" invisible=\\"1\\"/>\\n                                <div invisible=\\"not qr_code\\" colspan=\\"2\\" class=\\"text-center\\">\\n                                    <field name=\\"qr_code\\" widget=\\"html\\"/>\\n                                </div>\\n                            </group>\\n                        </group>\\n                        <group>\\n                            <!-- To be used in localizations requiring to add a page -->\\n                            <notebook name=\\"payment_notebook\\" colspan=\\"2\\"/>\\n                        </group>\\n                    </sheet>\\n                    <div class=\\"o_attachment_preview\\"/>\\n                    <chatter/>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Pay">\n                    <header>\n                        <button name="action_post" string="Confirm" type="object" class="oe_highlight" invisible="state != 'draft'" data-hotkey="q"/>\n                        <button name="action_validate" string="Validate" type="object" class="oe_highlight" invisible="state != 'in_process' or move_id" data-hotkey="q"/>\n                        <button name="action_reject" string="Reject" type="object" invisible="state != 'in_process' or not is_sent" data-hotkey="q"/>\n                        <button name="action_draft" string="Reset to Draft" type="object" class="btn btn-secondary" invisible="state in ('draft')" groups="account.group_account_invoice" data-hotkey="w"/>\n                        <button string="Request Cancel" name="button_request_cancel" type="object" groups="account.group_account_invoice" invisible="state != 'in_process' or not move_id or not need_cancel_request" data-hotkey="w"/>\n                        <button name="mark_as_sent" string="Mark as Sent" type="object" data-hotkey="v" invisible="state != 'in_process' or is_sent or payment_method_code != 'manual'"/>\n                        <button name="unmark_as_sent" string="Unmark as Sent" type="object" data-hotkey="k" invisible="state != 'in_process' or not is_sent or payment_method_code != 'manual'"/>\n                        <button name="action_cancel" string="Cancel" type="object" invisible="not id or not (state == 'draft' or (state == 'in_process' and is_sent))" data-hotkey="x"/>\n                        <field name="state" widget="statusbar" statusbar_visible="draft,in_process,paid"/>\n                    </header>\n                    <div class="alert alert-warning mb-2" role="alert" invisible="not duplicate_payment_ids or state!='draft'">\n                        <span>This payment has the same partner, amount and date as </span>\n                        <field name="duplicate_payment_ids" widget="x2many_buttons" string="Duplicated Payments"/>\n                    </div>\n                    <sheet>\n                        <!-- Invisible fields -->\n                        <field name="id" invisible="1"/>\n                        <field name="is_sent" invisible="1"/>\n                        <field name="need_cancel_request" invisible="1"/>\n                        <field name="is_reconciled" invisible="1"/>\n                        <field name="is_matched" invisible="1"/>\n                        <field name="payment_method_code" invisible="1"/>\n                        <field name="show_partner_bank_account" invisible="1"/>\n                        <field name="require_partner_bank_account" invisible="1"/>\n                        <field name="available_payment_method_line_ids" invisible="1"/>\n                        <field name="available_partner_bank_ids" invisible="1"/>\n                        <!-- <field name="suitable_journal_ids" invisible="1"/> -->\n                        <field name="country_code" invisible="1"/>\n                        <field name="partner_type" invisible="1"/>\n                        <field name="reconciled_invoices_type" invisible="1"/>\n                        <field name="company_id" invisible="1"/>\n                        <field name="paired_internal_transfer_payment_id" invisible="1"/>\n                        <field name="available_journal_ids" invisible="1"/>\n                        <field name="currency_id" invisible="1"/>\n\n                        <div class="oe_button_box" name="button_box">\n                            <!-- Invoice stat button -->\n                            <button name="button_open_invoices" type="object" class="oe_stat_button" icon="fa-bars" invisible="reconciled_invoices_count == 0">\n                                <div class="o_form_field o_stat_info">\n                                    <span class="o_stat_text">\n                                        <field name="reconciled_invoices_count"/>\n                                        <span invisible="reconciled_invoices_type != 'invoice'"> Invoice</span>\n                                        <span invisible="reconciled_invoices_type == 'invoice'"> Credit Note</span>\n                                    </span>\n                                </div>\n                            </button>\n\n                            <!-- Bill stat button -->\n                            <button name="button_open_bills" type="object" class="oe_stat_button" icon="fa-bars" invisible="reconciled_bills_count == 0">\n                                <div class="o_form_field o_stat_info">\n                                    <span class="o_stat_text">\n                                        <field name="reconciled_bills_count"/>\n                                        <span> Bill</span>\n                                    </span>\n                                </div>\n                            </button>\n\n                            <!-- Statement stat button -->\n                            <button name="button_open_statement_lines" type="object" class="oe_stat_button" icon="fa-bars" invisible="reconciled_statement_lines_count == 0">\n                                <div class="o_form_field o_stat_info">\n                                    <field name="reconciled_statement_lines_count"/>\n                                    <span class="o_stat_text">Transaction</span>\n                                </div>\n                            </button>\n\n                            <!-- Journal Entry  button -->\n                            <button name="button_open_journal_entry" type="object" class="oe_stat_button" icon="fa-bars" invisible="not move_id" groups="account.group_account_user,account.group_account_readonly">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text">Journal Entry</span>\n                                </div>\n                            </button>\n                        </div>\n\n                        <widget name="web_ribbon" text="Invoicing App Legacy" bg_color="text-bg-info" invisible="state != 'invoicing_legacy'" tooltip="This payment has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting."/>\n\n                        <div class="oe_title">\n                            <h1 invisible="state != 'draft'"><span>Draft</span></h1>\n                            <h1 invisible="state == 'draft'"><field name="name" readonly="1"/></h1>\n                        </div>\n\n                        <group name="main_group">\n                            <group name="group1">\n                                <field name="payment_type" widget="radio" options="{'horizontal': True}" readonly="state != 'draft'"/>\n                                <field name="partner_id" context="{'default_is_company': True}" string="Customer" options="{'no_quick_create': True}" invisible="partner_type != 'customer'" readonly="state != 'draft'"/>\n                                <field name="partner_id" context="{'default_is_company': True}" string="Vendor" options="{'no_quick_create': True}" invisible="partner_type != 'supplier'" readonly="state != 'draft'"/>\n                                <label for="amount"/>\n                                <div name="amount_div" class="o_row">\n                                    <field name="amount" readonly="state != 'draft'"/>\n                                    <field name="currency_id" options="{'no_create': True, 'no_open': True}" required="1" readonly="state != 'draft'" groups="base.group_multi_currency"/>\n                                </div>\n                                <field name="date" readonly="state != 'draft'"/>\n                                <field name="memo" string="Memo"/>\n                            </group>\n                            <group name="group2">\n                                <field name="journal_id" domain="[('id', 'in', available_journal_ids)]" readonly="state != 'draft'"/>\n                                <field name="payment_method_line_id" context="{'hide_payment_journal_id': 1}" options="{'no_create': True, 'no_open': True}" required="1" readonly="state != 'draft'"/>\n\n                                <field name="partner_bank_id" string="Customer Bank Account" context="{'default_partner_id': partner_id, 'display_account_trust': True}" invisible="not show_partner_bank_account or partner_type != 'customer' or payment_type == 'inbound'" required="require_partner_bank_account"/>\n\n                                <field name="partner_bank_id" string="Vendor Bank Account" context="{'default_partner_id': partner_id, 'display_account_trust': True}" invisible="not show_partner_bank_account or partner_type != 'supplier' or payment_type == 'inbound'" required="require_partner_bank_account"/>\n\n                                <!-- This field should always be readonly but using readonly="1" overrides the other partner_bank_id\n                                fields readonly condition in the framework, preventing the modification of these fields -->\n                                <field name="partner_bank_id" string="Company Bank Account" context="{'default_partner_id': partner_id, 'display_account_trust': True}" invisible="not show_partner_bank_account or payment_type == 'outbound'" required="require_partner_bank_account"/>\n                            </group>\n                            <group>\n                                <field name="qr_code" invisible="1"/>\n                                <div invisible="not qr_code" colspan="2" class="text-center">\n                                    <field name="qr_code" widget="html"/>\n                                </div>\n                            </group>\n                        </group>\n                        <group>\n                            <!-- To be used in localizations requiring to add a page -->\n                            <notebook name="payment_notebook" colspan="2"/>\n                        </group>\n                    </sheet>\n                    <div class="o_attachment_preview"/>\n                    <chatter/>\n                </form>\n            	f	t	2025-11-28 09:05:18.991518	2025-11-28 09:05:18.991518	f
1273	16	\N	1	1	todo_user_onboarding	\N	project_todo.todo_user_onboarding	qweb	project_todo/data/todo_template.xml	primary	{"en_US": "<t t-name=\\"project_todo.todo_user_onboarding\\">\\n<h1>\\n    <span style=\\"font-size: 36px; color: #374151\\">Hey <t t-out=\\"object.name\\"/> &amp;#128075; <br/>\\n    Welcome to the To-do app! </span>\\n</h1>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Use it to manage your work, take notes on the go, and create tasks based on them.\\n    </span>\\n</p>\\n<p><br/></p>\\n<h3>Using the editor</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">This private to-do is for you to play around with.</span>\\n    <br/>\\n    <span style=\\"font-size: 14px;\\">Ready to give it a spin?</span>\\n</p>\\n<p>\\n    <span style=\\"font-size: 14px;\\">Try the following</span>\\n</p>\\n<ul class=\\"o_checklist\\">\\n    <li id=\\"checkId-948702291173\\">\\n        <span style=\\"font-size: 14px;\\">Check this box to indicate it's done</span>\\n    </li>\\n    <li id=\\"checkId-140908257281\\">\\n        <span style=\\"font-size: 14px;\\">Click anywhere, and just start typing</span>\\n    </li>\\n    <li id=\\"checkId-441216037148\\">\\n        <span style=\\"font-size: 14px;\\">Press Ctrl+Z/⌘+Z to undo any change</span>\\n    </li>\\n    <li id=\\"checkId-980463482772\\">\\n        <span style=\\"font-size: 14px;\\">\\n            Select text to\\n            <font style=\\"background-color: #017E84; color: white\\">Highlight</font>,\\n            <span style=\\"text-decoration-line: line-through;\\">strikethrough</span>\\n            or\\n            <span style=\\"font-weight: bolder;\\">style</span>\\n            <span style=\\"font-style: italic; text-decoration-line: underline;\\">it</span>\\n        </span>\\n    </li>\\n    <li id=\\"checkId-152369821198\\">\\n        <span style=\\"font-size: 14px;\\">\\n            Below this list, try\\n            <span style=\\"font-weight: bolder;\\">commands</span>\\n            by\\n            <span style=\\"font-weight: bolder;\\">\\n                <font style=\\"color: #017E84\\">typing</font>\\n            </span>\\n            \\"<span style=\\"font-weight: bolder;\\">/</span>\\"\\n        </span>\\n    </li>\\n    <li class=\\"oe-nested\\" id=\\"checkId-947916154443\\">\\n        <ul class=\\"o_checklist\\">\\n            <li id=\\"checkId-1422510558483\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Add a checklist\\n                    (/<span style=\\"font-style: italic;\\">checklist</span>)\\n                </span>\\n            </li>\\n            <li id=\\"checkId-109605733655\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Add a separator\\n                    (/<span style=\\"font-style: italic;\\">separator</span>)\\n                </span>\\n            </li>\\n            <li id=\\"checkId-1518315885641\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Use\\n                    /<span style=\\"font-style: italic;\\">heading</span>\\n                    to convert a text into a title\\n                </span>\\n            </li>\\n        </ul>\\n    </li>\\n</ul>\\n<p><br/></p>\\n\\n<h3>Who has access to what?</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        By default, to-dos are only visible to you. You can share them with other users by adding them as\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">assignees</font>.\\n        </span>\\n    </span>\\n    <br/>\\n    <img class=\\"img-fluid d-none d-sm-block\\" src=\\"/project_todo/static/img/todo_access.png\\" alt=\\"todo-access\\"/>\\n</p>\\n<p><br/></p>\\n\\n<h3>Organize your to-dos however you want</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Customize the stages from the\\n        <span style=\\"font-weight: bolder;\\">\\n            <font class=\\"text-o-color-2\\">Kanban view</font>\\n        </span>\\n        to reflect your preferred workflow.\\n    </span>\\n</p>\\n<p><br/></p>\\n\\n<h3 class=\\"fw-bolder\\">Enhance Your To-Dos with Shortcuts &amp;#9889;</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Use these keywords in the title to streamline your to-dos:\\n    </span>\\n    <br/>\\n    <ul>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">#tags:</font>\\n            </span>\\n            Add tags to categorize the to-do\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">@user:</font>\\n            </span>\\n            Assign the to-do to a specific user\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">!:</font>\\n            </span>\\n            Mark the to-do as medium priority\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">!!:</font>\\n            </span>\\n            Mark the to-do as high priority\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">!!!:</font>\\n            </span>\\n            Mark the to-do as urgent\\n        </li>\\n    </ul>\\n    <br/>\\n    <span style=\\"font-size: 14px;\\">\\n        Ensure you follow the correct format and order. For example: Send invitations #event @Mitchell !\\n    </span>\\n</p>\\n<p><br/></p>\\n\\n<h3 class=\\"fw-bolder\\">Manage your to-dos and assigned tasks from a single place</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Access your personal pipeline with your to-dos and assigned tasks by going to the Project app and clicking\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">My Tasks</font>.\\n        </span>\\n    </span>\\n    <br/>\\n    <br/>\\n    <span style=\\"font-size: 14px;\\">\\n        There, your to-dos are listed as\\n        <span style=\\"font-weight: bolder;\\">\\n            <font class=\\"text-o-color-2\\">private tasks.</font>\\n        </span>\\n        Any task you create privately will also be included in your to-dos. Essentially, they are interchangeable.\\n    </span>\\n</p>\\n<p><br/></p>\\n\\n<h3>Convert to-dos into tasks</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        If you want to assign your to-do to a specific project, open the ⚙️ menu and click\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">Convert to Task</font>.\\n        </span>\\n        This action will make it visible to other users.\\n    </span>\\n    <br/>\\n    <img class=\\"img-fluid d-none d-sm-block\\" src=\\"/project_todo/static/img/convert_todo.png\\" alt=\\"convert-todo\\"/>\\n</p>\\n<p><br/></p>\\n\\n<h3>Create to-dos from anywhere</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Wherever you are, use the magic keyboard shortcut to add yourself a reminder &amp;#128161;\\n    </span>\\n    <br/>\\n    <ul>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">Alt + Shift + T</font>\\n            </span>\\n            (Windows/Linux)\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">Ctrl + Shift + T</font>\\n            </span>\\n            (MacOs)\\n        </li>\\n    </ul>\\n</p>\\n    </t>", "es_ES": "<t t-name=\\"project_todo.todo_user_onboarding\\">\\n<h1>\\n    <span style=\\"font-size: 36px; color: #374151\\">Hola <t t-out=\\"object.name\\"/> &amp;#128075; <br/>\\n    ¡Le damos la bienvenida a la aplicación Actividades pendientes! </span>\\n</h1>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Úsela para administrar su trabajo, tomar notas al instante y crear tareas.\\n    </span>\\n</p>\\n<p><br/></p>\\n<h3>Usando el editor</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">En esta actividad pendiente podrá probar todas las funciones que desee.</span>\\n    <br/>\\n    <span style=\\"font-size: 14px;\\">¿Está listo para explorar?</span>\\n</p>\\n<p>\\n    <span style=\\"font-size: 14px;\\">Intente lo siguiente</span>\\n</p>\\n<ul class=\\"o_checklist\\">\\n    <li id=\\"checkId-948702291173\\">\\n        <span style=\\"font-size: 14px;\\">Marque esta casilla para indicar que está hecha</span>\\n    </li>\\n    <li id=\\"checkId-140908257281\\">\\n        <span style=\\"font-size: 14px;\\">Haga clic en cualquier parte y solo comience a escribir</span>\\n    </li>\\n    <li id=\\"checkId-441216037148\\">\\n        <span style=\\"font-size: 14px;\\">Presione Ctrl+Z/⌘+Z para deshacer cualquier cambio</span>\\n    </li>\\n    <li id=\\"checkId-980463482772\\">\\n        <span style=\\"font-size: 14px;\\">\\n            Seleccione el texto para\\n            <font style=\\"background-color: #017E84; color: white\\">resaltarlo</font>,\\n            <span style=\\"text-decoration-line: line-through;\\">tacharlo</span>\\n            o\\n            <span style=\\"font-weight: bolder;\\">darle</span>\\n            <span style=\\"font-style: italic; text-decoration-line: underline;\\">estilo</span>\\n        </span>\\n    </li>\\n    <li id=\\"checkId-152369821198\\">\\n        <span style=\\"font-size: 14px;\\">\\n            Debajo de esta lista, pruebe los\\n            <span style=\\"font-weight: bolder;\\">comandos</span>\\n            ,\\n            <span style=\\"font-weight: bolder;\\">\\n                <font style=\\"color: #017E84\\">escribiendo</font>\\n            </span>\\n            \\"<span style=\\"font-weight: bolder;\\">/</span>\\"\\n        </span>\\n    </li>\\n    <li class=\\"oe-nested\\" id=\\"checkId-947916154443\\">\\n        <ul class=\\"o_checklist\\">\\n            <li id=\\"checkId-1422510558483\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Añadir una lista de comprobación\\n                    (/<span style=\\"font-style: italic;\\">lista de comprobación</span>)\\n                </span>\\n            </li>\\n            <li id=\\"checkId-109605733655\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Añadir un separador\\n                    (/<span style=\\"font-style: italic;\\">separador</span>)\\n                </span>\\n            </li>\\n            <li id=\\"checkId-1518315885641\\">\\n                <span style=\\"font-size: 14px;\\">\\n                    Utilicar \\n                    /<span style=\\"font-style: italic;\\">título</span>\\n                    para convertir el texto a título\\n                </span>\\n            </li>\\n        </ul>\\n    </li>\\n</ul>\\n<p><br/></p>\\n\\n<h3>¿Quién tiene acceso a qué?</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Por defecto, las tareas pendientes sólo son visibles para usted. Puede compartirlas con otros usuarios si los añade como\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">personas asignadas</font>.\\n        </span>\\n    </span>\\n    <br/>\\n    <img class=\\"img-fluid d-none d-sm-block\\" src=\\"/project_todo/static/img/todo_access.png\\" alt=\\"todo-access\\"/>\\n</p>\\n<p><br/></p>\\n\\n<h3>Organice sus actividades pendientes como quiera</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Personalice las etapas con la\\n        <span style=\\"font-weight: bolder;\\">\\n            <font class=\\"text-o-color-2\\">vista de kanban</font>\\n        </span>\\n        para que coincidan con su flujo de trabajo preferido.\\n    </span>\\n</p>\\n<p><br/></p>\\n\\n<h3 class=\\"fw-bolder\\">Enhance Your To-Dos with Shortcuts &amp;#9889;</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Use these keywords in the title to streamline your to-dos:\\n    </span>\\n    <br/>\\n    <ul>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">#tags:</font>\\n            </span>\\n            Add tags to categorize the to-do\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">@user:</font>\\n            </span>\\n            Assign the to-do to a specific user\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">!:</font>\\n            </span>\\n            Mark the to-do as medium priority\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">!!:</font>\\n            </span>\\n            Mark the to-do as high priority\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">!!!:</font>\\n            </span>\\n            Mark the to-do as urgent\\n        </li>\\n    </ul>\\n    <br/>\\n    <span style=\\"font-size: 14px;\\">\\n        Ensure you follow the correct format and order. For example: Send invitations #event @Mitchell !\\n    </span>\\n</p>\\n<p><br/></p>\\n\\n<h3 class=\\"fw-bolder\\">Gestione sus actividades pendientes y tareas asignadas desde un solo lugar</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Acceda a su flujo y sus tareas pendientes desde la aplicación de Proyecto y luego haga clic en\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">Mis tareas</font>.\\n        </span>\\n    </span>\\n    <br/>\\n    <br/>\\n    <span style=\\"font-size: 14px;\\">\\n        Allí aparecerán su actividades pendientes como\\n        <span style=\\"font-weight: bolder;\\">\\n            <font class=\\"text-o-color-2\\">tareas privadas.</font>\\n        </span>\\n        Todas las tareas que cree en privado también aparecerán en sus actividades pendientes.\\n    </span>\\n</p>\\n<p><br/></p>\\n\\n<h3>Convertir las actividades pendientes en tareas</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Si desea asignar su actividad pendiente a un proyecto específico, abra el menú ⚙️ y haga clic en\\n        <span>\\n            <font style=\\"font-weight: bolder;\\" class=\\"text-o-color-2\\">Convertir en tarea</font>.\\n        </span>\\n        Esta acción hará que otros usuarios puedan verla.\\n    </span>\\n    <br/>\\n    <img class=\\"img-fluid d-none d-sm-block\\" src=\\"/project_todo/static/img/convert_todo.png\\" alt=\\"convert-todo\\"/>\\n</p>\\n<p><br/></p>\\n\\n<h3>Cree actividades pendientes desde cualquier lugar</h3>\\n<hr/>\\n<p>\\n    <span style=\\"font-size: 14px;\\">\\n        Use los atajos del teclado para añadir sus recordatorios &amp;#128161;\\n    </span>\\n    <br/>\\n    <ul>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">Alt + Shift + T</font>\\n            </span>\\n            (Windows/Linux)\\n        </li>\\n        <li>\\n            <span style=\\"font-weight: bolder;\\">\\n                <font class=\\"text-o-color-2\\">Ctrl + Shift + T</font>\\n            </span>\\n            (MacOS)\\n        </li>\\n    </ul>\\n</p>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="project_todo.todo_user_onboarding">\n<h1>\n    <span style="font-size: 36px; color: #374151">Hey <t t-out="object.name"/> &amp;#128075; <br/>\n    Welcome to the To-do app! </span>\n</h1>\n<p>\n    <span style="font-size: 14px;">\n        Use it to manage your work, take notes on the go, and create tasks based on them.\n    </span>\n</p>\n<p><br/></p>\n<h3>Using the editor</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">This private to-do is for you to play around with.</span>\n    <br/>\n    <span style="font-size: 14px;">Ready to give it a spin?</span>\n</p>\n<p>\n    <span style="font-size: 14px;">Try the following</span>\n</p>\n<ul class="o_checklist">\n    <li id="checkId-948702291173">\n        <span style="font-size: 14px;">Check this box to indicate it's done</span>\n    </li>\n    <li id="checkId-140908257281">\n        <span style="font-size: 14px;">Click anywhere, and just start typing</span>\n    </li>\n    <li id="checkId-441216037148">\n        <span style="font-size: 14px;">Press Ctrl+Z/⌘+Z to undo any change</span>\n    </li>\n    <li id="checkId-980463482772">\n        <span style="font-size: 14px;">\n            Select text to\n            <font style="background-color: #017E84; color: white">Highlight</font>,\n            <span style="text-decoration-line: line-through;">strikethrough</span>\n            or\n            <span style="font-weight: bolder;">style</span>\n            <span style="font-style: italic; text-decoration-line: underline;">it</span>\n        </span>\n    </li>\n    <li id="checkId-152369821198">\n        <span style="font-size: 14px;">\n            Below this list, try\n            <span style="font-weight: bolder;">commands</span>\n            by\n            <span style="font-weight: bolder;">\n                <font style="color: #017E84">typing</font>\n            </span>\n            "<span style="font-weight: bolder;">/</span>"\n        </span>\n    </li>\n    <li class="oe-nested" id="checkId-947916154443">\n        <ul class="o_checklist">\n            <li id="checkId-1422510558483">\n                <span style="font-size: 14px;">\n                    Add a checklist\n                    (/<span style="font-style: italic;">checklist</span>)\n                </span>\n            </li>\n            <li id="checkId-109605733655">\n                <span style="font-size: 14px;">\n                    Add a separator\n                    (/<span style="font-style: italic;">separator</span>)\n                </span>\n            </li>\n            <li id="checkId-1518315885641">\n                <span style="font-size: 14px;">\n                    Use\n                    /<span style="font-style: italic;">heading</span>\n                    to convert a text into a title\n                </span>\n            </li>\n        </ul>\n    </li>\n</ul>\n<p><br/></p>\n\n<h3>Who has access to what?</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        By default, to-dos are only visible to you. You can share them with other users by adding them as\n        <span>\n            <font style="font-weight: bolder;" class="text-o-color-2">assignees</font>.\n        </span>\n    </span>\n    <br/>\n    <img class="img-fluid d-none d-sm-block" src="/project_todo/static/img/todo_access.png" alt="todo-access"/>\n</p>\n<p><br/></p>\n\n<h3>Organize your to-dos however you want</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        Customize the stages from the\n        <span style="font-weight: bolder;">\n            <font class="text-o-color-2">Kanban view</font>\n        </span>\n        to reflect your preferred workflow.\n    </span>\n</p>\n<p><br/></p>\n\n<h3 class="fw-bolder">Enhance Your To-Dos with Shortcuts &amp;#9889;</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        Use these keywords in the title to streamline your to-dos:\n    </span>\n    <br/>\n    <ul>\n        <li>\n            <span style="font-weight: bolder;">\n                <font class="text-o-color-2">#tags:</font>\n            </span>\n            Add tags to categorize the to-do\n        </li>\n        <li>\n            <span style="font-weight: bolder;">\n                <font class="text-o-color-2">@user:</font>\n            </span>\n            Assign the to-do to a specific user\n        </li>\n        <li>\n            <span style="font-weight: bolder;">\n                <font class="text-o-color-2">!:</font>\n            </span>\n            Mark the to-do as medium priority\n        </li>\n        <li>\n            <span style="font-weight: bolder;">\n                <font class="text-o-color-2">!!:</font>\n            </span>\n            Mark the to-do as high priority\n        </li>\n        <li>\n            <span style="font-weight: bolder;">\n                <font class="text-o-color-2">!!!:</font>\n            </span>\n            Mark the to-do as urgent\n        </li>\n    </ul>\n    <br/>\n    <span style="font-size: 14px;">\n        Ensure you follow the correct format and order. For example: Send invitations #event @Mitchell !\n    </span>\n</p>\n<p><br/></p>\n\n<h3 class="fw-bolder">Manage your to-dos and assigned tasks from a single place</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        Access your personal pipeline with your to-dos and assigned tasks by going to the Project app and clicking\n        <span>\n            <font style="font-weight: bolder;" class="text-o-color-2">My Tasks</font>.\n        </span>\n    </span>\n    <br/>\n    <br/>\n    <span style="font-size: 14px;">\n        There, your to-dos are listed as\n        <span style="font-weight: bolder;">\n            <font class="text-o-color-2">private tasks.</font>\n        </span>\n        Any task you create privately will also be included in your to-dos. Essentially, they are interchangeable.\n    </span>\n</p>\n<p><br/></p>\n\n<h3>Convert to-dos into tasks</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        If you want to assign your to-do to a specific project, open the ⚙️ menu and click\n        <span>\n            <font style="font-weight: bolder;" class="text-o-color-2">Convert to Task</font>.\n        </span>\n        This action will make it visible to other users.\n    </span>\n    <br/>\n    <img class="img-fluid d-none d-sm-block" src="/project_todo/static/img/convert_todo.png" alt="convert-todo"/>\n</p>\n<p><br/></p>\n\n<h3>Create to-dos from anywhere</h3>\n<hr/>\n<p>\n    <span style="font-size: 14px;">\n        Wherever you are, use the magic keyboard shortcut to add yourself a reminder &amp;#128161;\n    </span>\n    <br/>\n    <ul>\n        <li>\n            <span style="font-weight: bolder;">\n                <font class="text-o-color-2">Alt + Shift + T</font>\n            </span>\n            (Windows/Linux)\n        </li>\n        <li>\n            <span style="font-weight: bolder;">\n                <font class="text-o-color-2">Ctrl + Shift + T</font>\n            </span>\n            (MacOs)\n        </li>\n    </ul>\n</p>\n    </t>\n\n	f	t	2025-11-28 09:09:11.464237	2025-11-28 09:09:11.464237	f
