ice.invoice_user_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;city&quot;, &quot;phone&quot;]}"/>\n                                </t>\n                            </div>\n                        </div>\n                    </t>\n                </t>\n\n                <!-- Page Content -->\n                <div id="invoice_content" class="o_portal_content col-12 col-lg-8 col-xxl-9">\n                    <t t-if="error or warning" t-call="account.portal_invoice_error"/>\n                    <t t-if="success and (not error and not warning)" t-call="account.portal_invoice_success"/>\n\n                    <div class="o_portal_html_view position-relative bg-white shadow overflow-hidden">\n                        <div class="o_portal_html_loader text-center">\n                            <i class="fa fa-circle-o-notch fa-spin fa-2x fa-fw text-black-50"/>\n                        </div>\n                        <iframe id="invoice_html" class="position-relative d-block" width="100%" height="100%" frameborder="0" scrolling="no" t-att-src="invoice.get_portal_url(report_type='html')"/>\n                    </div>\n                    <!-- chatter -->\n                    <div id="invoice_communication" class="mt-4">\n                        <h3>Communication history</h3>\n                        <t t-call="portal.message_thread"/>\n                    </div>\n                </div>\n            </div>\n        </xpath>\n    <xpath expr="." position="attributes"><attribute name="t-name">account.portal_invoice_page</attribute></xpath></data>\n\n    	f	t	2025-11-28 09:05:18.991518	2025-11-28 09:05:18.991518	f
1005	16	\N	1	1	portal_invoice_required_fields_form	\N	account.portal_invoice_required_fields_form	qweb	account/views/account_portal_templates.xml	primary	{"en_US": "<t t-name=\\"account.portal_invoice_required_fields_form\\">\\n        <t t-foreach=\\"required_fields\\" t-as=\\"required_field\\">\\n            <div t-attf-class=\\"mb-3 col-xl-6\\">\\n                <!-- select by default the value passed in the data or corresponding to the \\"default\\" attribute on the field -->\\n                <t t-set=\\"field_info\\" t-value=\\"env[required_field.model]._fields[required_field.name]\\"/>\\n                <t t-set=\\"default_value\\" t-value=\\"extra_field_values.get(field_prefix + required_field.name) or field_info.default and field_info.default(required_field.model)\\"/>\\n                <t t-if=\\"required_field.ttype == 'selection'\\">\\n                    <label class=\\"col-form-label\\" t-att-for=\\"field_prefix + required_field.name\\"><t t-out=\\"required_field.field_description\\"/></label>\\n                    <select class=\\"form-select\\" t-att-name=\\"field_prefix + required_field.name\\" required=\\"required\\">\\n                        <option t-att-selected=\\"not default_value\\" disabled=\\"disabled\\" value=\\"\\"><t t-out=\\"'Select the %s ...' % required_field.field_description.lower()\\"/></option>\\n                        <t t-foreach=\\"required_field.selection_ids\\" t-as=\\"selection\\">\\n                            <option t-att-selected=\\"default_value and default_value == selection.value\\" t-att-value=\\"selection.value\\"><t t-out=\\"selection.name\\"/></option>\\n                        </t>\\n                    </select>\\n                </t>\\n            </div>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="account.portal_invoice_required_fields_form">\n        <t t-foreach="required_fields" t-as="required_field">\n            <div t-attf-class="mb-3 col-xl-6">\n                <!-- select by default