enter\\" role=\\"status\\">\\n                        La cuenta de destino seleccionada está configurada para usar una moneda específica. Cada entrada transferida se convertirá a esta moneda, lo que provocará\\n                        la pérdida de cualquier importe en moneda extranjera preexistente.\\n                    </div>\\n                    <div invisible=\\"not lock_date_message\\" class=\\"alert alert-warning text-center\\" role=\\"status\\">\\n                        <field name=\\"lock_date_message\\" nolabel=\\"1\\"/>\\n                    </div>\\n                    <group>\\n                        <group invisible=\\"action != 'change_period'\\">\\n                            <field name=\\"date\\" string=\\"Fecha de reconocimiento\\"/>\\n                            <field name=\\"expense_accrual_account\\" string=\\"Cuenta de devengo\\" invisible=\\"account_type != 'expense'\\" required=\\"account_type == 'expense' and action == 'change_period'\\"/>\\n                            <field name=\\"revenue_accrual_account\\" string=\\"Cuenta de devengo\\" invisible=\\"account_type != 'income'\\" required=\\"account_type == 'income' and action == 'change_period'\\"/>\\n                        </group>\\n                        <group invisible=\\"action != 'change_account'\\">\\n                            <field name=\\"date\\" string=\\"Fecha de transferencia\\"/>\\n                            <field name=\\"destination_account_id\\" required=\\"action == 'change_account'\\"/>\\n                        </group>\\n                        <group>\\n                            <label for=\\"total_amount\\" string=\\"Importe de ajuste\\" invisible=\\"action != 'change_period'\\"/>\\n                            <div invisible=\\"action != 'change_period'\\">\\n                                <field name=\\"percentage\\" style=\\"width:40% !important\\" readonly=\\"action != 'change_period'\\"/>%<span class=\\"px-3\\"/>(<field name=\\"total_amount\\" class