e=\\"not duplicate_payment_ids\\">\\n                        <span>This payment has the same partner, amount and date as </span>\\n                        <field name=\\"duplicate_payment_ids\\" widget=\\"x2many_buttons\\" string=\\"Duplicated Payments\\"/>\\n                    </div>\\n                    <div role=\\"alert\\" invisible=\\"not actionable_errors\\">\\n                        <field name=\\"actionable_errors\\" widget=\\"actionable_errors\\" class=\\"w-100\\"/>\\n                    </div>\\n                    <group>\\n                        <group name=\\"group1\\">\\n                            <field name=\\"journal_id\\" options=\\"{'no_open': True, 'no_create': True}\\" required=\\"1\\"/>\\n                            <field name=\\"payment_method_line_id\\" context=\\"{'hide_payment_journal_id': 1}\\" required=\\"1\\" options=\\"{'no_create': True, 'no_open': True}\\"/>\\n                            <field name=\\"partner_bank_id\\" invisible=\\"not show_partner_bank_account or not can_edit_wizard or (can_group_payments and not group_payment)\\" readonly=\\"payment_type == 'inbound'\\" required=\\"require_partner_bank_account and can_edit_wizard and (not can_group_payments or not group_payment)\\" placeholder=\\"Account Number\\" context=\\"{'display_account_trust': True, 'default_partner_id': partner_id}\\"/>\\n                            <field name=\\"group_payment\\" invisible=\\"not can_group_payments\\"/>\\n                            <label for=\\"payment_difference\\" invisible=\\"not show_payment_difference\\"/>\\n                            <div invisible=\\"not show_payment_difference\\">\\n                                <field name=\\"payment_difference\\"/>\\n                                <field name=\\"payment_difference_handling\\" widget=\\"radio\\" nolabel=\\"1\\" invisible=\\"is_register_payment_on_draft\\"/>\\n                                <div class=\\"o_inner_group grid col-lg-12 p-0\\" invisible=\\"hide_writeoff_section or payment_difference_handling == 'open'\\">\\n                                    <div class=\\"o_wrap_field d-flex d-sm-contents flex-column mb-3 mb-sm-0\\">\\n                                        <div class=\\"o_cell o_wrap_label text-break text-900\\">\\n                                            <label for=\\"writeoff_account_id\\" string=\\"Post Difference In\\" class=\\"oe_edit_only\\"/>\\n                                        </div>\\n                                        <div class=\\"o_cell o_wrap_input text-break\\">\\n                                            <field name=\\"writeoff_account_id\\" string=\\"Post Difference In\\" options=\\"{'no_create': True}\\" required=\\"payment_difference_handling == 'reconcile' and not early_payment_discount_mode\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <div class=\\"o_wrap_field d-flex d-sm-contents flex-column mb-3 mb-sm-0\\">\\n                                        <div class=\\"o_cell o_wrap_label text-break text-900\\">\\n                                            <label for=\\"writeoff_label\\" class=\\"oe_edit_only\\" string=\\"Label\\" invisible=\\"writeoff_is_exchange_account\\"/>\\n                                        </div>\\n                                        <div class=\\"o_cell o_wrap_input text-break\\">\\n                                            <field name=\\"writeoff_label\\" required=\\"payment_difference_handling == 'reconcile'\\" invisible=\\"writeoff_is_exchange_account\\"/>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                        </group>\\n                        <group name=\\"group2\\">\\n                            <label for=\\"amount\\"/>\\n                            <div name=\\"amount_div\\" class=\\"o_row\\">\\n          