e="padding: 10px 0px 20px 20px;" class="p0" colspan="2">\n                                <span class="header_date">November 26, 2025</span>\n                            </td>\n                        </tr>\n                    </tbody>\n                </table>\n            </td>\n        </tr>\n    </tbody>\n</table>\n<table cellspacing="0" cellpadding="0" border="0" style="width: 100%;background-color: #F9FAFB;">\n    <tbody>\n        <tr>\n            <td align="center">\n                <table cellspacing="0" cellpadding="0" border="0" class="global_layout">\n                    <tbody>\n                        <tr>\n                            <td colspan="3" style="width: 100%;padding: 20px;border: 1px solid #F9FAFB;">\n                                <table>\n                                    <tbody>\n                                        <tr>\n                                            <td><div>\n    <p class="tip_title">Consejo: acelere su flujo de trabajo con accesos rápidos</p>\n    <p class="tip_content">Presiona ALT en cualquier pantalla para resaltar accesos rápidos para cada botón en la pantalla. Es útil para procesar múltiples documentos en lote.</p>\n    <img src="https://download.odoocdn.com/digests/digest/static/src/img/milk-alt-shortcuts.gif" width="540" class="illustration_border">\n</div>\n            </td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </td>\n                        </tr>\n                        <tr>\n                            <td style="padding: 20px 20px 0px 20px;" class="global_td">\n                                <table style="width: 100%;" cellspacing="0" cellpadding="0">\n                                    <tr>\n                                        <td style="padding-bottom: 20px;">\n                                            <table cellspacing="0" cellpadding="10" style="width: 100%;margin-bottom: 5px;" data-field="kpi_res_users_connected">\n                                                <tr class="kpi_header">\n                                                    <td colspan="2" style="padding: 0px 0px 5px 0px;">\n                                                        <span style="text-transform: uppercase;">Usuarios conectados</span>\n                                                    </td>\n                                                </tr>\n                                                <tr style="vertical-align: top;">\n                                                    <td class="kpi_cell" style="padding-top: 10px; border-top: 1px solid #e6e6e6;">\n                                                        <div>\n<span style="color: #374151;text-decoration: none;" class="kpi_value kpi_border_col">0</span>\n<br/>\n<span class="kpi_value_label">Últimas 24 horas</span>\n                                                        </div>\n                                                    </td>\n                                                    <td class="kpi_cell" style="padding-top: 10px; border-top: 1px solid #e6e6e6;">\n                                                        <div>\n<span style="color: #374151;text-decoration: none;" class="kpi_value kpi_border_col">1</span>\n<br/>\n<span class="kpi_value_label">Últimos 7 días</span>\n                                                        </div>\n                                                    </td>\n                                                    <td class="kpi_cell" style="padding-top: 10px; border-top: 1px solid #e6e6e6;">\n                                                        <div>\n<span style="color: #374151;text-decoration: none;" class="kpi_value kpi_border_col">1</span>\n<br/>\n<span class="kpi_value_label">Últimos 30 días</span>\n                                                        </div>\n                                                    </td>\n                       