ion: none !important; font-weight: 400; background-color: {{ object.email_secondary_color or '#875A7B' }}; border-radius:3px\\">\\n                                            Send invoices\\n                                        </a>\\n                                    </div>\\n                                </td>\\n                                <td valign=\\"middle\\" align=\\"right\\">\\n                                    <t t-if=\\"not object.uses_default_logo\\">\\n                                        <img t-att-src=\\"'/logo.png?company=%s' % object.id\\" style=\\"height: auto; width: 80px; margin-right: 10px;\\" t-att-alt=\\"'%s' % object.name\\"/>\\n                                    </t>\\n                                </td>\\n                            </tr>\\n                            <tr>\\n                                <td colspan=\\"2\\" style=\\"text-align:center;\\">\\n                                    <hr style=\\"background-color:#CCCCCC; border:none; height:1px; margin:16px 0;\\"/>\\n                                </td>\\n                            </tr>\\n                        </table>\\n                    </td>\\n                </tr>\\n                <!-- BODY -->\\n                <tr>\\n                    <td align=\\"center\\">\\n                        <table width=\\"590\\" cellpadding=\\"0\\" cellspacing=\\"0\\" style=\\"padding: 0px 8px; background-color: white; border-collapse:separate;\\">\\n                            <tr>\\n                                <td style=\\"font-size: 14px;\\">\\n                                    <p>Dear <t t-out=\\"object.name or ''\\">YourCompany</t>,</p>\\n\\n                                    <p>We have successfully added your company to the <strong>Peppol Network</strong>.</p>\\n\\n                                    <p>You can now <strong>send<t t-if=\\"object.account_peppol_proxy_state == 'receiver'\\"> and receive</t></strong> electronic invoices via Odoo — completely 